/* Contenido de «Diplomado de Asistente Administrativo y Recepción». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("d-asistente-administrativo",{"l":{"d-asistente-administrativo-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un <b>diplomado libre de capacitación</b> con constancia de Instituto Mara: no tiene validez oficial de la SEP ni es una certificación de CONOCER. Te prepara con habilidades prácticas para trabajar en oficina y recepción, pero no garantiza un empleo. En los temas de facturas y datos personales te damos lo básico para tu trabajo diario; <b>no sustituye la asesoría de un contador o de un abogado</b>."},{"tipo":"texto","texto":"En casi cualquier lugar donde llega gente o se mueven papeles hace falta alguien que <b>ordene, atienda y dé seguimiento</b>. A ese puesto le llaman de muchas formas: recepcionista, auxiliar administrativo, asistente de dirección, asistente de oficina, secretaria. Cambia el nombre, pero el corazón es el mismo: que las cosas <b>no se caigan</b>. Que el recado llegue, que la cita no se empalme, que el documento aparezca cuando se necesita y que la caja cuadre."},{"tipo":"tabla","titulo":"El mismo puesto en distintos lugares","encabezados":["Lugar","Funciones típicas","Lo que más cuidan"],"filas":[["<b>Consultorio o clínica</b>","Agendar y confirmar citas, recibir pacientes, cobrar consultas, llenar datos de expediente","Trato amable, puntualidad de la agenda, confidencialidad de datos de salud"],["<b>Despacho</b> (contable, jurídico, arquitectura)","Atender llamadas, recibir clientes, archivar, llevar la agenda de los socios, enviar documentos","Orden en el archivo, discreción, redacción correcta"],["<b>Hotel</b>","Registro de entrada y salida, reservaciones, informes, atención de quejas, cobro","Paciencia, trabajo por turnos, resolver rápido"],["<b>Escuela</b>","Atender a madres y padres, inscripciones, control de pagos, circulares, archivo de alumnos","Organización por fechas, trato con familias, cuidado de datos de menores"],["<b>Empresa u oficina</b>","Agenda del jefe, juntas, viajes, compras de papelería, caja chica, facturas de proveedores","Seguimiento, discreción, control de gastos"]]},{"tipo":"tarjetas","rotulo":"Palabras que vas a oír en el trabajo","tarjetas":[{"frente":"Recado","reverso":"Mensaje que tomas para alguien que no está. Completo lleva quién, de dónde, para quién, qué, teléfono, fecha y hora."},{"frente":"Minuta","reverso":"Resumen escrito de una junta: quién estuvo, qué se acordó, quién hace qué y para cuándo."},{"frente":"Caja chica","reverso":"Dinero en efectivo que se guarda en la oficina para gastos pequeños y urgentes."},{"frente":"Requisición","reverso":"Solicitud interna para pedir que se compre algo."},{"frente":"Seguimiento","reverso":"Revisar que algo pendiente sí se haga, sin esperar a que alguien pregunte."}]},{"tipo":"relacionar","rotulo":"¿Qué cuidas más en cada lugar?","pares":[["Consultorio","Datos de salud de los pacientes"],["Hotel","Reservaciones y cambios de turno"],["Escuela","Datos de alumnos menores de edad"],["Despacho","Expedientes de clientes bien archivados"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La función que une a todos estos puestos es…","ops":["Vender productos de la empresa","Hacer la contabilidad fiscal","Ordenar, atender y dar seguimiento para que nada se caiga"],"correcta":2,"explica":"Por eso las empresas valoran tanto a alguien confiable en este puesto."},{"p":"Un documento que resume acuerdos de una junta se llama…","ops":["Recado","Minuta","Requisición"],"correcta":1},{"p":"«Dar seguimiento» significa…","ops":["Revisar que un pendiente sí se cumpla sin esperar a que te pregunten","Pasar el pendiente a otra persona y olvidarlo","Anotarlo solo si te lo piden por escrito"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Dónde te ves","pregunta":"¿En qué tipo de lugar te gustaría trabajar primero: consultorio, despacho, hotel, escuela u oficina? ¿Qué de tu experiencia (aunque sea fuera de una oficina) te sirve para ese lugar?","ayuda":"Me veo en… porque… Ya sé… (por ejemplo, atender clientes en un negocio familiar, llevar cuentas de una tanda, organizar eventos)."},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la recepcionista que «solo contestaba el teléfono»</b><br>Liliana entró como recepcionista a un consultorio de ortodoncia en Zapopan. Pensó que su trabajo era contestar el teléfono. En su primera semana le pidieron confirmar citas del día siguiente, cobrar, pedir facturas a proveedores y cuidar que nadie viera los expedientes en el mostrador. Se sintió rebasada.<br>Recepción y asistencia administrativa tienen el mismo corazón: ordenar, atender y dar seguimiento. Cada lugar pide cuidados distintos."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué cuidado especial tiene un consultorio?","ops":["El inventario de dulces","Tener revistas nuevas","La agenda de citas y la confidencialidad de los expedientes"],"correcta":2,"explica":"La información de salud de los pacientes es confidencial."},{"p":"¿Qué habría ayudado a Liliana en su primera semana?","ops":["Esperar a que le expliquen todo","Hacer solo lo que le gusta","Pedir una lista de funciones y hacer su propia lista de pendientes diaria"],"correcta":2,"explica":"Tomar la iniciativa de ordenar sus funciones reduce el estrés."},{"p":"¿Qué validez tiene la constancia de este diplomado?","ops":["Es un título profesional","Es una constancia libre de Instituto Mara, no validez SEP ni certificación CONOCER","Es una certificación oficial"],"correcta":1,"explica":"Conviene decirlo con claridad en tu CV."}]},{"tipo":"comparar","titulo":"Cómo se oye al empezar","mal":"«Yo nomás contesto el teléfono.»","bien":"«Mis funciones son recibir pacientes, confirmar citas, cobrar, pedir facturas y cuidar los expedientes. Cada mañana reviso mi lista y la agenda del día.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Elige un tipo de lugar (consultorio, despacho, escuela, hotel, agencia) y escribe diez funciones reales de su recepción o asistencia administrativa.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe cuáles de esas funciones ya sabes hacer y cuáles te toca aprender en este diplomado.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Descripción de funciones del puesto","texto":"FUNCIONES DEL PUESTO — [Lugar]\nAtención: [recibir, contestar, canalizar]\nAgenda: [citas, confirmaciones, juntas]\nDocumentos: [correos, oficios, archivo]\nAdministración: [caja chica, compras, facturas]\nCuidados especiales del lugar: [confidencialidad, datos de menores, seguridad]\nA quién reporto: [ ]\nHerramientas que uso: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Recepción y asistencia administrativa tienen el mismo corazón: ordenar, atender y dar seguimiento.","Cada lugar pide cuidados distintos: agenda en consultorios, archivo en despachos, datos de menores en escuelas.","Este diplomado es libre, con constancia de Instituto Mara; no es validez SEP ni certificación CONOCER."]}],"d-asistente-administrativo-m1-l2":[{"tipo":"texto","texto":"Quien está en recepción es la <b>primera impresión</b> del lugar. Antes de conocer al doctor, al licenciado o al gerente, la gente te conoce a ti. Eso no significa vestir caro: significa verse <b>limpio, ordenado y acorde al lugar</b>, hablar con respeto y cuidar lo que dices."},{"tipo":"lista","items":["<b>Imagen:</b> ropa limpia y planchada, acorde al código del lugar (no es lo mismo un hotel de playa que un despacho jurídico). Si hay uniforme, úsalo completo.","<b>Trato:</b> saluda primero, usa el nombre de la persona, «usted» con quien no conoces y tutea solo si el lugar lo acostumbra.","<b>Puntualidad:</b> llegar 10 minutos antes para abrir, encender equipo y revisar la agenda.","<b>Celular personal:</b> guardado mientras atiendes. Nada da peor imagen que alguien esperando mientras la recepcionista ve videos.","<b>Tu espacio:</b> escritorio despejado, sin papeles de otros a la vista."]},{"tipo":"destacado","texto":"<b>Confidencialidad</b> es no contar ni dejar ver lo que conoces por tu trabajo: sueldos, diagnósticos, problemas legales de clientes, conversaciones del jefe, datos personales. Es de las razones más comunes para perder la confianza (y el empleo). Regla simple: <b>si no lo necesitan saber para trabajar, no lo cuentas</b>, ni en la oficina, ni en tu casa, ni en redes sociales."},{"tipo":"comparar","titulo":"Misma situación, dos respuestas","malTitulo":"Así no","mal":"Llama alguien que dice ser hermano de un paciente: «¿A qué hora es la cita de mi hermano y qué tiene?». La recepcionista le dice la hora y que «viene por lo de sus análisis de azúcar».","bienTitulo":"Así sí","bien":"«Con gusto le ayudo, pero no puedo dar información de citas ni de salud de otra persona. Si gusta, le pido a su hermano que se comunique con usted o que él mismo nos llame»."},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"Una compañera te pregunta cuánto gana el nuevo gerente, porque tú viste el contrato. Tú…","ops":["Le dices solo el rango aproximado","Le enseñas el contrato para que ella lo vea","Le dices amablemente que no puedes compartir esa información"],"correcta":2,"explica":"Aunque sea «solo un rango», es información confidencial que conociste por tu puesto."},{"p":"Un proveedor te ofrece un regalo si su factura se paga antes que las demás. Tú…","ops":["Lo aceptas y no le dices a nadie","Lo rechazas con cortesía y avisas a tu jefe según la política del lugar","Lo aceptas si es algo pequeño"],"correcta":1,"explica":"Aceptar regalos a cambio de favores es un conflicto de interés."},{"p":"Tienes que tirar copias con datos de clientes. Lo correcto es…","ops":["Triturarlas o destruirlas como indique el lugar","Tirarlas enteras al bote de basura","Usarlas como hojas de reciclaje para recados"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la regla","items":[{"frase":"Si no lo necesitan saber para ___, no lo cuentas.","resp":["trabajar"]},{"frase":"Aceptar un regalo a cambio de un favor en el trabajo es un conflicto de ___.","resp":["interés","interes"]}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la plática en el elevador</b><br>Andrea es asistente en un despacho de abogados en Monterrey. En el elevador comentó con una amiga, sin decir nombres, que «el señor del divorcio famoso vino hoy». Alguien la escuchó, supo de quién hablaba y lo publicó en redes. Otro día, un proveedor le ofreció una canasta navideña «para que le ayude con los pagos».<br>Lo que conoces por tu trabajo no se cuenta ni se deja ver. Regalos a cambio de favores son un riesgo de ética."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué error cometió Andrea en el elevador?","ops":["Hablar con una amiga","Comentar información del trabajo que permitió identificar a un cliente","Usar el elevador"],"correcta":1,"explica":"Aunque no digas nombres, los detalles pueden identificar a alguien."},{"p":"¿Qué hacer con la canasta del proveedor?","ops":["Pedir una más grande","Consultar la política de regalos y no aceptarla si es a cambio de favores","Aceptarla, es Navidad"],"correcta":1,"explica":"Un regalo condicionado compromete tu trabajo."},{"p":"¿Qué incluye la imagen profesional en recepción?","ops":["Ropa de marca","Limpieza, orden, puntualidad y el celular guardado","Maquillaje llamativo"],"correcta":1,"explica":"Eres la primera impresión del lugar."}]},{"tipo":"comparar","titulo":"Cómo se responde al proveedor","mal":"«Ay, gracias, sí le ayudo con sus pagos.»","bien":"«Muchas gracias, pero por política no puedo aceptarlo. Sus pagos siguen el proceso normal; con gusto le digo en qué etapa van.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe cinco situaciones de riesgo de confidencialidad o ética que podrían pasarle a una recepcionista y cómo respondería en cada una.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Reglas personales de confidencialidad","texto":"MIS REGLAS DE CONFIDENCIALIDAD\n1. No comento casos, clientes ni pacientes fuera del trabajo, aunque no diga nombres.\n2. Pantalla bloqueada al levantarme.\n3. Nada de documentos a la vista en el mostrador.\n4. Por teléfono no doy datos de otra persona sin verificar.\n5. Papel confidencial: a trituradora, no al bote.\n6. Regalos: consulto la política antes de aceptar.\nDudas: las consulto con [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["En recepción eres la primera impresión: limpio, ordenado, puntual y con el celular guardado.","Confidencialidad: lo que conoces por tu trabajo no se cuenta ni se deja ver.","Regalos a cambio de favores, datos de otra persona por teléfono y papeles tirados enteros son riesgos de ética."]}],"d-asistente-administrativo-m1-l3":[{"tipo":"texto","texto":"Una vacante trae mucha información escondida. Leerla bien te ahorra postularte a lo que no te conviene y te dice <b>qué palabras poner en tu CV</b>. Muchas empresas filtran currículums con sistemas que buscan palabras clave; si la vacante dice «manejo de agenda» y tu CV dice «organicé citas», a veces el sistema no te encuentra."},{"tipo":"tabla","titulo":"Descifra la vacante","encabezados":["La vacante dice…","Lo que en realidad busca","Qué pones en tu CV"],"filas":[["«Manejo de Office / paquetería»","Word, Excel básico (sumas, filtros) y correo","Las herramientas concretas que usas: «Excel: sumas, filtros, BUSCARV»"],["«Excelente presentación»","Imagen limpia y trato amable (no se refiere a tu físico)","Experiencia atendiendo público"],["«Proactiva, con iniciativa»","Que des seguimiento sin que te lo pidan","Un logro donde tú resolviste algo"],["«Disponibilidad de horario»","Turnos o sábados; pregunta cuáles antes de aceptar","Tu disponibilidad real"],["«Sueldo atractivo» o «a convenir»","No dice cifra; pregunta el rango en la primera llamada","Nada; es tema para la entrevista"]],"nota":"La Ley Federal del Trabajo (art. 133) prohíbe al patrón negarse a contratar por edad, género, embarazo, discapacidad, origen o religión, entre otros motivos, y exigir certificado de no embarazo. Si ves una vacante así, no es tu culpa: es una práctica discriminatoria."},{"tipo":"destacado","texto":"<b>Alerta de fraude:</b> ninguna empresa seria te cobra por entrevistarte, por un «curso de inducción obligatorio» o por el uniforme antes de contratarte. Tampoco pide tu contraseña bancaria ni tu NIP. Si te piden depositar para «apartar tu lugar», es fraude."},{"tipo":"plantilla","rotulo":"CV de una página para recepción o asistente","texto":"NOMBRE COMPLETO\nCiudad, Estado · Teléfono · correo profesional (nombre.apellido@...)\n\nPERFIL (3 líneas)\nRecepcionista con [X] años atendiendo público en [giro]. Manejo de agenda, llamadas y cobro. Organizada, puntual y con buen trato. Busco crecer como asistente administrativa.\n\nEXPERIENCIA\n[Puesto] — [Empresa], [Ciudad] | [mes/año] a [mes/año]\n• Atendí en promedio [número] llamadas y visitas al día.\n• Llevé la agenda de [número] doctores/socios sin empalmes.\n• Controlé la caja chica y entregué arqueos semanales sin diferencias.\n\nESTUDIOS\n[Nivel] — [Escuela], [año]\nDiplomado de Asistente Administrativo y Recepción — Instituto Mara (curso libre), [año]\n\nHABILIDADES\nExcel (sumas, filtros, CONTAR.SI, BUSCARV) · Word · Correo y calendario · Atención telefónica · Inglés [nivel real]\n\nDISPONIBILIDAD\n[Horario y días]","nota":"En México no es obligatorio poner foto, edad, estado civil ni CURP en el CV. Si no tienes experiencia formal, pon lo que sí has hecho: negocio familiar, servicio social, voluntariado, ventas por catálogo."},{"tipo":"comparar","titulo":"Cómo describir lo que hiciste","malTitulo":"Débil","mal":"«Encargada de recepción. Responsable de contestar el teléfono y atender a la gente.»","bienTitulo":"Fuerte","bien":"«Atendí unas 40 llamadas y 25 pacientes al día en un consultorio de 3 médicos; reduje las citas empalmadas confirmando un día antes por WhatsApp.»"},{"tipo":"ordenar","rotulo":"Ordena la frase de un buen logro","items":[{"frase":"Confirmé las citas por WhatsApp y bajaron las inasistencias"},{"frase":"Organicé el archivo de clientes por año y apellido"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si la vacante pide «manejo de agenda», en tu CV conviene…","ops":["Cambiarlas por sinónimos para verte original","No mencionarlo si no fue tu función principal","Usar esas mismas palabras al describir tu experiencia"],"correcta":2,"explica":"Repetir las palabras de la vacante ayuda a los filtros automáticos y a quien lee rápido."},{"p":"Te piden $800 para «apartar tu lugar» en el proceso. Es…","ops":["Un depósito que te regresan con el primer sueldo","Una señal de fraude","Un trámite normal"],"correcta":1},{"p":"Un CV para recepción idealmente mide…","ops":["Una página","Tres páginas","Lo que haga falta, entre más largo mejor"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el mismo CV para todas</b><br>Pedro mandó su CV a 40 vacantes de auxiliar administrativo en Puebla y nadie le llamó. Su CV tiene tres páginas, una foto de fiesta, un correo «el_pedrin_chido@…» y dice «responsable, puntual y con ganas de aprender». Una vacante pedía «control de caja chica y Excel intermedio» y él lo había hecho en su trabajo anterior, pero no lo puso.<br>Lee la vacante como pista: sus palabras clave van en tu CV. Describe logros con números y verbos."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué debió cambiar primero?","ops":["Ponerle colores","Mandarlo a más vacantes","Adaptar el CV a cada vacante con sus palabras clave"],"correcta":2,"explica":"Si la vacante pide caja chica y tú la manejaste, dilo."},{"p":"¿Cuál es una buena forma de describir experiencia?","ops":["«Hice muchas cosas en la oficina»","«Responsable y puntual»","«Controlé una caja chica de $5,000 con arqueo semanal sin diferencias»"],"correcta":2,"explica":"Verbo + qué + número o resultado."},{"p":"Una «agencia» te pide $800 para agendarte entrevistas. Eso es…","ops":["normal","una inversión","una señal de fraude: nadie serio cobra por entrevistar o contratar"],"correcta":2,"explica":"Desconfía de cualquier cobro por conseguir empleo."}]},{"tipo":"comparar","titulo":"Cómo se describe la experiencia","mal":"«Responsable, puntual y con ganas de aprender.»","bien":"«Atendí a 60 clientes diarios en mostrador, controlé la caja chica con arqueo semanal y organicé el archivo de 800 expedientes.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Busca una vacante real de asistente o recepción y escribe sus cinco palabras clave más importantes.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Redacta tres logros para tu CV con verbo, acción y número, pensados para esa vacante.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"CV de una página","texto":"NOMBRE COMPLETO\nCiudad · Teléfono · correo profesional (nombre.apellido@…)\n\nPERFIL (2 líneas con palabras clave de la vacante)\n[ ]\n\nEXPERIENCIA\n[Puesto] — [Empresa] — [Fechas]\n• [Verbo + qué + número]\n• [ ]\n\nHABILIDADES: [hoja de cálculo nivel ___, facturación, atención telefónica…]\nFORMACIÓN: [escolaridad] · Diplomado de Asistente Administrativo y Recepción (constancia de Instituto Mara)","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Lee la vacante como pista: sus palabras clave van en tu CV.","Describe logros con números y verbos: atendí, organicé, reduje, controlé.","Nadie serio te cobra por entrevistarte o contratarte."]}],"d-asistente-administrativo-m1-l4":[{"tipo":"texto","texto":"La <b>carta de presentación</b> (o el mensaje que mandas con tu CV por correo o por una bolsa de trabajo) sirve para una cosa: que quieran abrir tu CV. Debe ser corta, hecha para <b>esa</b> vacante y sin faltas de ortografía. Una carta genérica se nota de inmediato."},{"tipo":"plantilla","rotulo":"Carta o correo de presentación","texto":"Asunto: Postulación a Recepcionista — [Tu nombre]\n\nEstimada [nombre de la persona o «equipo de Recursos Humanos»]:\n\nLe escribo para postularme a la vacante de [puesto] publicada en [dónde la viste]. Tengo [experiencia breve: X años atendiendo público en…] y me interesa trabajar en [empresa] porque [algo concreto: su giro, su ubicación, su trato con pacientes].\n\nEn mi experiencia anterior [un logro con número]. Manejo [herramientas que pide la vacante] y tengo disponibilidad de [horario].\n\nAdjunto mi CV. Quedo atenta a una entrevista en el horario que les convenga. Mi teléfono es [número].\n\nSaludos cordiales,\n[Nombre completo]","nota":"Cuida el nombre del archivo: «CV_Laura_Mendez_Recepcion.pdf», no «cv final final 2.docx». Mándalo en PDF para que no se desacomode."},{"tipo":"pasos","rotulo":"Prepara tu entrevista","pasos":["Investiga el lugar: a qué se dedica, dónde está, cómo llegar y cuánto tardas.","Relee la vacante y tu CV: debes poder explicar cada línea.","Prepara 3 ejemplos cortos de tu experiencia con el formato <b>situación, qué hiciste y resultado</b>.","Prepara 2 preguntas para ellos: horario real, funciones del día a día, prestaciones.","Llega 10 minutos antes, con tu CV impreso y una pluma.","Al terminar, agradece y, si te dieron un correo, manda un mensaje breve de agradecimiento ese mismo día."]},{"tipo":"tabla","titulo":"Preguntas frecuentes y cómo contestarlas","encabezados":["Pregunta","Idea para contestar"],"filas":[["«Háblame de ti»","Un minuto: qué has hecho, qué sabes hacer y por qué te interesa este puesto. No tu historia de vida."],["«¿Por qué dejaste tu último trabajo?»","Sé honesta y breve, sin hablar mal de nadie: «Buscaba crecer en tareas administrativas»."],["«¿Cuál es tu mayor defecto?»","Uno real y lo que haces para mejorarlo: «Me cuesta decir no; ahora anoto todo y digo cuándo sí puedo»."],["«¿Cómo manejarías a un cliente molesto?»","Escuchar, disculparte por la molestia, ofrecer solución o canalizar, y dar seguimiento."],["«¿Cuánto quieres ganar?»","Da un rango investigado para ese puesto en tu ciudad y di que es negociable según prestaciones."]]},{"tipo":"comparar","titulo":"La respuesta a «¿por qué quieres este trabajo?»","malTitulo":"Así no","mal":"«Pues porque necesito trabajar y me queda cerca.»","bienTitulo":"Así sí","bien":"«Me gusta atender gente y organizar. Vi que es una clínica con varios especialistas y me interesa aprender a llevar agendas más grandes. Además, vivo cerca, así que puedo ser muy puntual.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El mejor formato para mandar tu CV por correo es…","ops":["Una foto del CV impreso","Word con el nombre «cv final»","PDF con un nombre de archivo claro"],"correcta":2,"explica":"El PDF se ve igual en cualquier teléfono o computadora."},{"p":"En la entrevista te preguntan por qué dejaste tu último empleo. Lo mejor es…","ops":["Decir que te corrieron injustamente y cambiar de tema","Responder breve y honesto, sin hablar mal de nadie","Contar todos los problemas que tuviste con tu jefe"],"correcta":1},{"p":"Una buena forma de contar tu experiencia es…","ops":["Situación, qué hiciste y resultado","Solo los nombres de las empresas","Leer tu CV en voz alta"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu minuto","pregunta":"Escribe tu respuesta a «Háblame de ti» para una vacante de recepción o asistente. Léela en voz alta con cronómetro: que dure alrededor de un minuto.","ayuda":"Soy… He trabajado/estudiado… Sé hacer… Me interesa este puesto porque…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «háblame de ti»</b><br>En su entrevista para recepcionista de un hotel en Cancún, Carla contestó a «háblame de ti» con su historia desde la primaria. Cuando le preguntaron por una situación difícil con un cliente, dijo «no me ha pasado». Al final, le preguntaron si tenía dudas y dijo «no, ninguna». Otra candidata, con menos experiencia, se quedó con el puesto.<br>Prepara tres ejemplos con situación, acción y resultado, y dos preguntas para ellos. Carta corta y hecha para esa vacante."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cómo conviene responder «háblame de ti»?","ops":["Tu historia completa","Un minuto: quién eres, tu experiencia relevante y por qué te interesa el puesto","Solo tu nombre"],"correcta":1,"explica":"Breve y enfocado en el puesto."},{"p":"Ante «cuéntame de una situación difícil», lo mejor es…","ops":["hablar mal de un jefe anterior","un ejemplo con situación, acción y resultado","decir que nunca te ha pasado"],"correcta":1,"explica":"Demuestra cómo actúas."},{"p":"Al final, ¿qué preguntar?","ops":["Algo del puesto, como «¿cómo sería un día típico?»","Nada","Solo el sueldo y las vacaciones"],"correcta":0,"explica":"Hacer preguntas muestra interés."}]},{"tipo":"comparar","titulo":"Cómo se contesta la pregunta difícil","mal":"«No, nunca me ha pasado nada difícil.»","bien":"«En la tienda, un cliente llegó molesto por un cobro doble (situación). Lo escuché, revisé el ticket y pedí el reembolso con mi supervisora (acción). Se fue tranquilo y regresó la semana siguiente (resultado).»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe tres ejemplos con situación, acción y resultado de tu vida laboral, escolar o familiar que puedas contar en una entrevista.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Redacta una carta de presentación de máximo 150 palabras para una vacante real.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Preparación de entrevista","texto":"PREPARACIÓN DE ENTREVISTA — [Empresa]\n«Háblame de ti» (1 minuto): [ ]\nEjemplo 1 (atención a cliente): situación [ ] · acción [ ] · resultado [ ]\nEjemplo 2 (organización): [ ]\nEjemplo 3 (error y aprendizaje): [ ]\nMis preguntas: 1. [ ] 2. [ ]\nLlevo: CV impreso, identificación, pluma\nDespués: mensaje de agradecimiento el mismo día","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Carta corta, hecha para esa vacante y sin faltas: su trabajo es que abran tu CV.","Prepara 3 ejemplos con situación, acción y resultado, y 2 preguntas para ellos.","Nunca hables mal de empleos anteriores y agradece al terminar."]}],"d-asistente-administrativo-m1-lab":[{"tipo":"destacado","texto":"Encontraste esta vacante: <b>«Auxiliar administrativo — Grupo Médico del Valle, León. Requisitos: atención a pacientes, agenda de citas, manejo de caja chica, hoja de cálculo intermedia, redacción. Horario de 8 a 4. Ofrecemos prestaciones de ley.»</b> Tienes experiencia en una tienda de ropa y en la oficina de tu tío."},{"tipo":"texto","texto":"<p><b>Escena 1 — La vacante.</b> La lees tres veces.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe las palabras clave de la vacante y qué experiencia tuya responde a cada una.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — El CV.</b> Tu CV actual es genérico.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe el perfil y tres logros adaptados a esta vacante.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — La carta.</b> Te piden una carta de presentación.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Redacta la carta en máximo 150 palabras.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — La entrevista.</b> Te preguntan: «¿Por qué dejaste tu último empleo?» y «¿Cómo manejarías a un paciente molesto por la espera?».</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Escribe tus respuestas a las dos preguntas.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"¿Qué experiencia de la tienda de ropa sirve aquí?","ops":["Solo la de doblar ropa","Atención a clientes, manejo de caja y trato con personas molestas","Ninguna"],"correcta":1,"explica":"Las habilidades se transfieren entre puestos."},{"p":"Ante «¿por qué dejaste tu último empleo?», conviene…","ops":["responder breve y positivo, sin hablar mal de nadie","contar los problemas con tu jefe","no contestar"],"correcta":0,"explica":"Enfócate en lo que buscas ahora."},{"p":"Después de la entrevista…","ops":["envías un mensaje breve de agradecimiento el mismo día","llamas diario","esperas sin hacer nada"],"correcta":0,"explica":"El agradecimiento te distingue."}]},{"tipo":"plantilla","rotulo":"Postulación completa","texto":"POSTULACIÓN — [Empresa y puesto]\n□ Palabras clave de la vacante\n□ CV adaptado (una página)\n□ Carta de presentación (máx. 150 palabras)\n□ Tres ejemplos con situación, acción y resultado\n□ Dos preguntas para la empresa\n□ Mensaje de agradecimiento\nFecha de envío: [ ]  Seguimiento: [ ]","nota":"Cópiala y úsala en tu trabajo."}],"d-asistente-administrativo-m2-l1":[{"tipo":"texto","texto":"En recepción pasan dos cosas al mismo tiempo: llega gente y suena el teléfono. La regla de oro es <b>que nadie se sienta ignorado</b>. Si estás en una llamada y llega alguien, lo saludas con la mirada y un gesto («un momento, por favor»). Si estás atendiendo a alguien y suena el teléfono, contestas, saludas y pides permiso para dejarlo en espera unos segundos, o tomas el número para regresar la llamada."},{"tipo":"pasos","rotulo":"Protocolo para contestar una llamada","pasos":["Contesta antes del tercer timbre, con una sonrisa (se escucha en la voz).","Saludo completo: «Buenos días, Clínica San Rafael, le atiende Laura, ¿en qué le puedo ayudar?».","Escucha sin interrumpir y toma nota del nombre de quien llama; úsalo en la conversación.","Si vas a transferir, di a quién y por qué: «Le comunico con el área de facturación, que le puede ayudar con eso».","Si vas a dejar en espera, pide permiso y regresa cada 30 a 40 segundos a decir que sigues en ello.","Si la persona buscada no está, ofrece tomar un recado o que le regresen la llamada.","Despídete confirmando lo acordado: «Queda su cita el jueves a las 10. Gracias por llamar»."]},{"tipo":"tabla","titulo":"Frases que suenan profesionales","encabezados":["En lugar de…","Mejor di…"],"filas":[["«¿Quién habla?»","«¿Me permite su nombre, por favor?»"],["«No está»","«En este momento no se encuentra, ¿gusta dejarle un recado?»"],["«No sé»","«Permítame verificarlo y le confirmo»"],["«Espéreme»","«¿Me permite un momento en la línea? Enseguida regreso con usted»"],["«Eso no me toca»","«Le comunico con quien le puede ayudar con eso»"]]},{"tipo":"comparar","titulo":"Cuando llega alguien mientras hablas por teléfono","malTitulo":"Así no","mal":"La recepcionista sigue en la llamada sin voltear. El visitante espera de pie tres minutos sin saber si lo vieron.","bienTitulo":"Así sí","bien":"La recepcionista levanta la vista, sonríe, hace una seña de «un momento» y le señala la sala. Termina la llamada con brevedad y dice: «Gracias por esperar, ¿en qué le ayudo?»."},{"tipo":"ordenar","rotulo":"Ordena el saludo telefónico","items":[{"frase":"Buenos días Despacho Herrera le atiende Laura"},{"frase":"Permítame verificarlo y enseguida le confirmo"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si dejas a alguien en espera, conviene regresar a la línea cada…","ops":["5 minutos","Solo cuando ya tengas la respuesta","30 a 40 segundos"],"correcta":2,"explica":"Si la espera se alarga, ofrece regresar la llamada."},{"p":"La persona buscada no está. Lo mejor es…","ops":["Dar su celular personal","Ofrecer tomar un recado o que le regresen la llamada","Decir «no está» y colgar"],"correcta":1},{"p":"«Eso no me toca» se cambia por…","ops":["«Le comunico con quien le puede ayudar con eso»","«Llame más tarde»","«No sé, pregunte en otro lado»"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la señora que esperó sin que nadie la mirara</b><br>En la recepción de una notaría en Querétaro, la recepcionista estaba en una llamada larga con un proveedor. Una señora entró, se paró frente al mostrador y esperó cuatro minutos sin que nadie la mirara. Se sentó molesta. Luego la recepcionista transfirió una llamada sin decir a quién y la llamada se cortó.<br>Que nadie se sienta ignorado: saluda con la mirada aunque estés en una llamada. Transfiere diciendo a quién y por qué."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué debió hacer al ver entrar a la señora?","ops":["Colgarle al proveedor","Terminar la llamada primero sin mirarla","Saludarla con la mirada o un gesto y pedirle un momento"],"correcta":2,"explica":"Un gesto dice «ya te vi, enseguida te atiendo»."},{"p":"Un saludo telefónico completo incluye…","ops":["el nombre del jefe","solo «¿bueno?»","buenos días, nombre del lugar, tu nombre y en qué puedes ayudar"],"correcta":2,"explica":"El saludo completo da confianza."},{"p":"Si pones a alguien en espera, regresas cada…","ops":["30 a 40 segundos","5 minutos","cuando se acabe la música"],"correcta":0,"explica":"Regresar muestra que no lo olvidaste."}]},{"tipo":"comparar","titulo":"Cómo se transfiere","mal":"«Espéreme… [transfiere sin avisar].»","bien":"«Le comunico con la licenciada Ruiz, de escrituras, que es quien lleva su trámite. Si se corta, su extensión es la 214.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe el guion completo de atención telefónica para un lugar que conozcas: saludo, espera, transferencia, toma de recado y despedida.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Protocolo de atención","texto":"PROTOCOLO — [Lugar]\nPRESENCIAL: mirar y saludar al entrar · «Buenos días, bienvenido a [ ]» · ofrecer asiento si hay espera\nTELÉFONO: «Buenos días, [lugar], le atiende [nombre], ¿en qué le puedo ayudar?»\nESPERA: pedir permiso · regresar cada 30–40 s · ofrecer devolver la llamada\nTRANSFERIR: decir a quién, por qué y dar la extensión\nDESPEDIDA: «¿Hay algo más en que pueda ayudarle? Que tenga buen día.»","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Que nadie se sienta ignorado: saluda con la mirada si estás en una llamada.","Saludo completo: buenos días, lugar, tu nombre y en qué le ayudas.","Transfiere diciendo a quién y por qué; en espera, regresa cada 30 a 40 segundos."]}],"d-asistente-administrativo-m2-l2":[{"tipo":"texto","texto":"Un recado incompleto es casi peor que no tomarlo: «Te habló un señor, que le marques». ¿Quién? ¿A qué número? ¿Para qué? Un <b>recado completo</b> responde siete preguntas. Si lo tomas en papel, usa un formato; si lo mandas por mensaje o correo, respeta el mismo orden."},{"tipo":"plantilla","rotulo":"Formato de recado","texto":"RECADO\nPara: [nombre de quien recibe]\nDe: [nombre completo de quien llamó]\nEmpresa o relación: [empresa, paciente, proveedor, familiar]\nTeléfono: [número completo, confirmado en voz alta]\nMensaje: [qué necesita, con sus palabras]\nAcción: [le devuelve la llamada / él vuelve a llamar / solo informar]\nUrgencia: [normal / urgente, antes de las __]\nFecha y hora: [día, hora]\nRecibió: [tu nombre]","nota":"Repite el número en voz alta en pares: «55 12 34 56 78, ¿es correcto?». Es el dato que más se equivoca."},{"tipo":"texto","texto":"En consultorios y despachos, además de agendar, conviene <b>medir</b>: cuántas citas se cumplieron, cuántas se cancelaron y cuántas personas no llegaron sin avisar. Con eso el jefe decide si confirmar un día antes, cobrar anticipo o abrir más horarios. La función <b>CONTAR.SI</b> cuenta cuántas celdas de un rango cumplen una condición: <b>=CONTAR.SI(rango, criterio)</b>."},{"tipo":"excel","rotulo":"Citas del lunes: Consultorio Médico Ruiz y Campos","datos":[["Hora","Paciente","Médico","Estado","","Resumen","Total"],["09:00","Karla Mena","Dra. Ruiz","Asistió","","Asistió",""],["09:30","Jorge Salas","Dr. Campos","Asistió","","Canceló",""],["10:00","Rosa Ibarra","Dra. Ruiz","Canceló","","No asistió",""],["10:30","Pedro Luna","Dra. Ruiz","No asistió","","Citas de la Dra. Ruiz",""],["11:00","Ana Torres","Dr. Campos","Asistió","","% de inasistencia",""],["11:30","Luis Paz","Dr. Campos","Asistió"],["12:00","Sofía Reyes","Dr. Campos","No asistió"],["12:30","Mario Gil","Dr. Campos","Asistió"],["13:00","Elena Cruz","Dra. Ruiz","Canceló"],["13:30","Raúl Vega","Dr. Campos","Asistió"]],"retos":[{"celda":"G2","formula":"=CONTAR.SI($D$2:$D$11,F2)","esperado":6,"requiere":"CONTAR.SI(","texto":"<b>G2</b>: cuenta cuántas citas tienen el estado «Asistió». Usa CONTAR.SI con el rango de estados y el criterio de F2.","pista":"=CONTAR.SI($D$2:$D$11,F2). Los signos $ fijan el rango para copiar la fórmula hacia abajo."},{"celda":"G3","formula":"=CONTAR.SI($D$2:$D$11,F3)","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>G3</b>: cuenta las cancelaciones."},{"celda":"G4","formula":"=CONTAR.SI($D$2:$D$11,F4)","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>G4</b>: cuenta las citas en las que el paciente no llegó ni avisó."},{"celda":"G5","formula":"=CONTAR.SI($C$2:$C$11,\"Dra. Ruiz\")","esperado":4,"requiere":"CONTAR.SI(","texto":"<b>G5</b>: cuenta cuántas citas tuvo agendadas la Dra. Ruiz (columna C).","pista":"El criterio de texto va entre comillas y debe escribirse igual que en la tabla: \"Dra. Ruiz\"."},{"celda":"G6","formula":"=REDONDEAR(G4/CONTARA($B$2:$B$11)*100,1)","esperado":20,"requiere":"CONTARA(","texto":"<b>G6</b>: porcentaje de inasistencia: las citas «No asistió» entre el total de citas (cuéntalas con CONTARA en la columna B), por 100, redondeado a 1 decimal.","explica":"2 de 10 pacientes no llegaron: 20%. Con ese dato, el consultorio puede decidir confirmar todas las citas un día antes por WhatsApp."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Un recado completo incluye el ___ de quien llamó, confirmado en voz alta.","resp":["teléfono","telefono","número","numero"]},{"frase":"Para contar cuántas celdas cumplen una condición se usa la función ___.","resp":["CONTAR.SI","contar.si"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál recado está completo?","ops":["«Le habló una señora, que le marque»","«Llamaron de una papelería por una factura»","«Lic. Pérez: llamó Martha Gómez, de Papelera del Centro, 55 1234 5678, sobre la factura de agosto; le regresa la llamada hoy. Lunes 10:15. Laura»"],"correcta":2,"explica":"Tiene quién, de dónde, teléfono, qué, acción, fecha, hora y quién recibió."},{"p":"=CONTAR.SI(D2:D11,\"Canceló\") devuelve…","ops":["El primer paciente que canceló","Cuántas celdas de D2:D11 dicen «Canceló»","La suma de las cancelaciones en pesos"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el recado «te habló alguien»</b><br>El director de una escuela en Morelia encontró en su escritorio un papelito: «Te habló el de los uniformes, que le hables». No decía nombre, teléfono, hora ni qué quería. Era el proveedor avisando que el pedido llegaría tarde. Se enteraron cuando los niños ya estaban formados para la foto. Además, nadie sabía cuántas citas con padres se habían perdido ese mes.<br>Un recado completo no deja dudas. Repite el teléfono en voz alta. Y CONTAR.SI te dice cuántas citas se cumplieron, cancelaron o se perdieron."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué dato se equivoca más en un recado?","ops":["El nombre del día","La hora","El número de teléfono"],"correcta":2,"explica":"Repítelo en voz alta para confirmarlo."},{"p":"¿Qué le faltaba al recado?","ops":["Una carita feliz","Solo la fecha","Nombre, empresa, teléfono, mensaje concreto, urgencia, hora y quién lo tomó"],"correcta":2,"explica":"Un recado completo permite actuar sin volver a preguntar."},{"p":"Para contar citas con estado «No asistió» se usa…","ops":["SUMA","PROMEDIO","CONTAR.SI"],"correcta":2,"explica":"CONTAR.SI cuenta celdas que cumplen una condición."}]},{"tipo":"comparar","titulo":"Cómo se toma el recado","mal":"«Te habló el de los uniformes, que le hables.»","bien":"«Para: Director. De: Jorge Ramírez, Uniformes del Centro. Tel. 443 123 4567 (confirmado). Mensaje: el pedido llega el jueves, no el martes. Urgente: sí, por la foto. 10:40 a. m. Tomó: Rosa.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe tres recados completos a partir de llamadas imaginarias en una escuela, un consultorio y una empresa.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Arma la fórmula para contar citas asistidas, canceladas y no asistidas, y escribe qué harías si las inasistencias pasan de 15%.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Formato de recado y control de citas","texto":"RECADO\nPara: [ ]   De: [ ]   Empresa: [ ]\nTeléfono (repetido en voz alta): [ ]\nMensaje: [ ]\nAcción: □ Llamar  □ Le llamará  □ Solo aviso   Urgencia: □ Alta □ Normal\nFecha y hora: [ ]   Tomó: [ ]\n\nCONTROL DE CITAS\nFecha | Nombre | Estado (Asistió/Canceló/No asistió)\nAsistió: [=CONTAR.SI(C:C,\"Asistió\")]\nNo asistió: [=CONTAR.SI(C:C,\"No asistió\")]\n% inasistencia: [=B2/CONTARA(C2:C200)]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Recado completo: para quién, de quién, empresa, teléfono, mensaje, acción, urgencia, fecha, hora y quién lo tomó.","Repite el teléfono en voz alta: es el dato que más se equivoca.","CONTAR.SI te dice cuántas citas se cumplieron, cancelaron o se perdieron."]}],"d-asistente-administrativo-m2-l3":[{"tipo":"texto","texto":"Un buen correo de trabajo se entiende <b>sin tener que leerlo dos veces</b>. Tiene un asunto que dice de qué trata, un saludo, el mensaje en pocas líneas, lo que necesitas que la otra persona haga y una despedida con tus datos. Antes de enviar, revisa tres cosas: destinatario correcto, archivo adjunto y ortografía."},{"tipo":"plantilla","rotulo":"Correo formal para confirmar una junta","texto":"Asunto: Confirmación de junta — Revisión de contrato, jueves 12 de marzo, 11:00\n\nEstimado Ing. Robles:\n\nPor indicaciones de la Lic. Herrera, le confirmo la junta para revisar el contrato de mantenimiento:\n\nFecha: jueves 12 de marzo\nHora: 11:00 a 12:00\nLugar: Sala de juntas, Av. Juárez 120, piso 3, Guadalajara\n\nLe agradeceré traer la propuesta firmada por su representante legal. Si necesita cambiar el horario, por favor avíseme a más tardar el miércoles a las 14:00.\n\nSaludos cordiales,\n\nLaura Méndez\nAsistente de Dirección · Despacho Herrera y Asociados\nTel. 33 1234 5678","nota":"Pon en el asunto qué, cuándo y a qué hora. Así la persona lo encuentra rápido en su bandeja."},{"tipo":"comparar","titulo":"El mismo mensaje, dos versiones","malTitulo":"Así no","mal":"Asunto: (sin asunto)<br>«hola q tal oiga le mando lo q me pidio luego me dice», sin adjunto.","bienTitulo":"Así sí","bien":"Asunto: Cotización de papelería — marzo<br>«Buenos días, Lic. Ramírez. Le envío adjunta la cotización de papelería de marzo. Quedo atenta a su visto bueno para hacer el pedido. Saludos, Laura Méndez»."},{"tipo":"tabla","titulo":"WhatsApp de la empresa: reglas","encabezados":["Regla","Por qué"],"filas":[["Usa el número de la empresa, no tu celular personal","La conversación es de la empresa y sigue ahí aunque cambies de trabajo"],["Horario de atención en la descripción y mensaje automático fuera de horario","La gente sabe cuándo le responderán"],["Saluda, identifícate y contesta completo en un solo mensaje","Evita diez mensajes cortos seguidos"],["No mandes audios largos a clientes","No todos pueden escucharlos en ese momento"],["Nada de datos sensibles (diagnósticos, estados de cuenta) por mensaje sin autorización","Protege a la persona y a la empresa"],["Usa etiquetas o listas (por ejemplo: nuevo, cita agendada, pagado)","Ninguna conversación se queda sin responder"]],"nota":"WhatsApp Business permite, al momento de escribir, mensajes de ausencia, respuestas rápidas y etiquetas. Revisa las opciones de tu versión."},{"tipo":"relacionar","rotulo":"¿Qué parte del correo es?","pares":[["«Confirmación de junta — jueves 12, 11:00»","Asunto"],["«Estimado Ing. Robles:»","Saludo"],["«Le agradeceré traer la propuesta firmada»","Petición concreta"],["Nombre, puesto, empresa y teléfono","Firma"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Antes de enviar un correo revisa…","ops":["Destinatario, adjunto y ortografía","Solo que tenga emojis","Que sea lo más largo posible"],"correcta":0,"explica":"Olvidar el adjunto es el error más común: menciónalo y adjúntalo antes de escribir el mensaje."},{"p":"Un cliente escribe al WhatsApp de la empresa a las 22:00. Lo ideal es que…","ops":["Le contestes desde tu celular personal","No reciba nada hasta que alguien lo vea","Reciba un mensaje automático con el horario y se le conteste al día siguiente"],"correcta":2},{"p":"El asunto de un correo debe…","ops":["Decir solo «Hola»","Decir de qué trata y, si aplica, fecha y hora","Estar vacío para que lo abran por curiosidad"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el correo que se fue a todos</b><br>Rodrigo, asistente en una constructora de Tijuana, mandó la lista de sueldos al director por correo, pero eligió por error la lista de «todos». Otro día envió una cotización con el asunto «Hola» y sin adjunto. Además, contesta a clientes desde su WhatsApp personal a las 11 de la noche.<br>Correo claro: asunto concreto, mensaje breve, petición y firma. Revisa destinatario, adjunto y ortografía antes de enviar. El WhatsApp de empresa, con el número de la empresa y en horario."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué se revisa antes de enviar un correo?","ops":["Solo el asunto","Nada, se puede corregir después","Destinatario, adjunto y ortografía"],"correcta":2,"explica":"Un correo enviado no se regresa."},{"p":"Un buen asunto para la cotización es…","ops":["«Urgente!!!»","«Hola»","«Cotización de cimentación — Obra Las Palmas — 12 de mayo»"],"correcta":2,"explica":"El asunto dice de qué trata y ayuda a encontrarlo."},{"p":"¿Por qué no usar su WhatsApp personal?","ops":["No hay problema","Porque la comunicación y los datos del cliente deben quedar en el número de la empresa y en horario","Porque es más caro"],"correcta":1,"explica":"Si deja la empresa, los clientes se van con él."}]},{"tipo":"comparar","titulo":"Cómo se escribe el correo","mal":"«Asunto: Hola. Aquí está lo que me pidió. Saludos.» (sin adjunto)","bien":"«Asunto: Cotización de cimentación — Obra Las Palmas. Buen día, ing. Soto: le comparto la cotización solicitada (adjunta, PDF). ¿Me confirma si la revisamos el jueves? Saludos, Rodrigo Mena, Asistente de Dirección, ext. 105.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Redacta tres correos formales: una cotización enviada a un cliente, una solicitud de información a un proveedor y un aviso interno de cambio de horario.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Estructura de correo formal","texto":"Asunto: [tema concreto — referencia — fecha]\n\nBuen día, [nombre y título]:\n\n[Una frase de contexto.]\n[Mensaje principal en 2 a 4 líneas.]\n[Petición clara con fecha: «¿Me confirma antes del…?»]\n\nSaludos cordiales,\n[Nombre]\n[Puesto] · [Empresa]\n[Teléfono y extensión]\n\nAntes de enviar: □ destinatario □ adjunto □ ortografía □ copia a quien corresponde","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Correo claro: asunto concreto, saludo, mensaje breve, petición, despedida y firma.","Revisa destinatario, adjunto y ortografía antes de enviar.","El WhatsApp de empresa se usa con el número de la empresa, horario y sin datos sensibles."]}],"d-asistente-administrativo-m2-l4":[{"tipo":"texto","texto":"La recepción también es la <b>puerta de seguridad</b> del lugar. Saber quién entra, a qué viene y a qué hora sale protege a todos. Y como es el primer lugar al que llega la gente, también es donde llegan las quejas. Las dos cosas se manejan mejor con un método."},{"tipo":"pasos","rotulo":"Registro de visitantes","pasos":["Saluda y pregunta su nombre, empresa y a quién visita.","Anota nombre, empresa, persona visitada, motivo y hora de entrada (en libreta o sistema).","Avisa a la persona visitada antes de dejar pasar; si no está, ofrece esperar o dejar recado.","Entrega gafete de visitante si el lugar lo usa y explica hacia dónde ir.","A la salida, recoge el gafete y anota la hora."]},{"tipo":"destacado","texto":"<b>Datos personales en el registro:</b> pide solo lo necesario. Si se pide una identificación, lo usual es verla o registrar el tipo y folio según la política del lugar; <b>no fotocopies ni fotografíes credenciales</b> si el lugar no lo tiene establecido en su aviso de privacidad. Y nunca dejes la libreta de visitas abierta a la vista de todos."},{"tipo":"pasos","rotulo":"Cuatro pasos ante una queja","pasos":["<b>Escuchar</b> sin interrumpir, tomando nota; si la persona está alterada, invítala a un lugar más tranquilo.","<b>Disculparte</b> por la molestia sin culpar a otros: «Lamento mucho la espera».","<b>Solucionar</b> lo que esté en tus manos o canalizar con quien pueda, diciendo a quién y cuándo tendrá respuesta.","<b>Agradecer y dar seguimiento</b>: registra la queja y confirma después que sí se resolvió."]},{"tipo":"plantilla","rotulo":"Respuesta a una queja por espera","texto":"Señora Martínez, tiene toda la razón en estar molesta: su cita era a las 10:00 y ya son las 10:40. Le ofrezco una disculpa. El doctor tuvo una urgencia y calculo que la atenderá en unos 15 minutos. Si prefiere, le reagendo hoy mismo a la hora que le acomode. ¿Qué le conviene más?","nota":"Nombra el problema con datos concretos, da un tiempo realista y ofrece opciones."},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"Llega un técnico que dice venir a revisar los servidores, pero nadie te avisó. Tú…","ops":["Le pides que espere y confirmas con el área de sistemas antes de dejarlo pasar","Lo dejas pasar porque trae uniforme","Le pides que regrese otro día sin verificar"],"correcta":0,"explica":"Confirmar antes de dar acceso es una práctica básica de seguridad."},{"p":"Un cliente molesto levanta la voz en la sala de espera. Lo primero es…","ops":["Pedirle que se calme o se vaya","Ignorarlo hasta que se canse","Escucharlo y, si se puede, invitarlo a un lugar más tranquilo"],"correcta":2},{"p":"Al registrar visitantes, lo correcto es pedir…","ops":["Nada, para no incomodar","Solo los datos necesarios para el registro","Copia de su INE, comprobante de domicilio y CURP"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu queja más difícil","pregunta":"Recuerda una queja que viviste (como cliente o como empleado). ¿Qué hizo bien o mal quien la atendió? ¿Cómo la resolverías hoy con los cuatro pasos?","ayuda":"La queja fue… Quien atendió… Hoy yo escucharía…, diría…, ofrecería…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el visitante que nadie sabía que seguía adentro</b><br>En un corporativo de Guadalajara, un «técnico de la copiadora» entró sin registro, recorrió oficinas y se llevó una laptop. Nadie sabía a quién visitaba. El mismo día, un cliente llegó gritando porque su pedido llevaba dos semanas de retraso, y la recepcionista le respondió: «Eso no es mi área».<br>Recepción es puerta de seguridad: registra quién entra, a quién visita y a qué hora sale. Ante una queja: escuchar, disculparte, solucionar o canalizar, y dar seguimiento."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué debió pasar con el técnico?","ops":["Dejarlo pasar porque traía uniforme","Pedirle su credencial y quedársela","Registrarlo, confirmar con el área que lo esperaba y acompañarlo"],"correcta":2,"explica":"Confirmar la visita evita que entre cualquiera."},{"p":"¿Qué datos pedir a un visitante?","ops":["Su dirección personal","Solo los necesarios: nombre, empresa, a quién visita y hora","Copia de su INE y CURP"],"correcta":1,"explica":"No copies credenciales sin una política que lo respalde."},{"p":"«Eso no es mi área» ante una queja…","ops":["cierra el tema","enciende más al cliente; hay que escuchar y canalizar con seguimiento","es correcto"],"correcta":1,"explica":"Aunque no lo resuelvas tú, eres responsable de canalizar."}]},{"tipo":"comparar","titulo":"Cómo se atiende la queja","mal":"«Eso no es mi área.»","bien":"«Entiendo su molestia y le ofrezco una disculpa. Ahora mismo llamo al encargado de pedidos para que le diga la fecha exacta. Mientras, ¿gusta sentarse?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Diseña el procedimiento de registro de visitantes de una oficina: qué datos, quién autoriza, gafete y salida.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe cómo atenderías una queja fuerte en recepción, paso a paso, hasta el seguimiento.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Registro de visitantes y queja","texto":"REGISTRO DE VISITANTES\nFecha | Nombre | Empresa | A quién visita | ¿Confirmado? | Gafete | Entrada | Salida\n\nQUEJA EN RECEPCIÓN\n1. Escuchar sin interrumpir\n2. Disculparse por la experiencia\n3. Solucionar o canalizar (a quién: [ ])\n4. Decir qué sigue y cuándo\n5. Seguimiento: [fecha y responsable]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Recepción es puerta de seguridad: registra quién entra, a quién visita y a qué hora sale.","Pide solo los datos necesarios y no copies credenciales sin política que lo respalde.","Queja: escuchar, disculparte, solucionar o canalizar, y dar seguimiento."]}],"d-asistente-administrativo-m2-lab":[{"tipo":"destacado","texto":"Son las 9:00 en la recepción del <b>Consultorio Pediátrico Dra. Salas</b>, en Guadalajara. Hay cuatro mamás esperando, suena el teléfono, llega un proveedor de vacunas y una mamá se acerca molesta porque su cita era a las 8:30."},{"tipo":"texto","texto":"<p><b>Escena 1 — Todo al mismo tiempo.</b> Teléfono, proveedor y mamá molesta, a la vez.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe en qué orden atiendes y qué dices a cada uno para que nadie se sienta ignorado.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — El recado.</b> Llama el pediatra de guardia de un hospital para hablar con la doctora, que está en consulta.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe el recado completo.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — La queja.</b> La mamá dice que es la tercera vez que la hacen esperar.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Escribe cómo la atiendes, paso a paso, y qué seguimiento das.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — El correo.</b> Debes avisar por correo a todos los pacientes del día siguiente que la doctora llegará 30 minutos tarde.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Redacta el correo.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"Con alguien frente a ti y el teléfono sonando…","ops":["ignoras a la persona","ignoras el teléfono","saludas con la mirada, contestas y pides un momento a quien llama si es necesario"],"correcta":2,"explica":"Nadie debe sentirse ignorado."},{"p":"El correo a los pacientes debe ir…","ops":["con todos en «Para»","desde tu correo personal","con copia oculta para no exponer los correos de todos"],"correcta":2,"explica":"Los correos de los pacientes son datos personales."},{"p":"Para saber si el retraso es frecuente, ¿qué usarías?","ops":["Una encuesta anual","La memoria","El control de citas con CONTAR.SI por estado y hora real de atención"],"correcta":2,"explica":"Los datos ayudan a proponer cambios."}]},{"tipo":"plantilla","rotulo":"Bitácora de recepción","texto":"BITÁCORA — [Fecha]\nHora | Situación | Qué hice | Pendiente | Responsable\n\nRecados entregados: [ ]\nQuejas del día y seguimiento: [ ]\nCitas: asistió [ ] · canceló [ ] · no asistió [ ]","nota":"Cópiala y úsala en tu trabajo."}],"d-asistente-administrativo-m3-l1":[{"tipo":"texto","texto":"Un archivo bien hecho se mide con una prueba sencilla: <b>si te piden un documento, lo encuentras en menos de un minuto</b>, y si tú faltas, otra persona también lo encuentra. Para eso hace falta elegir un método, escribirlo y que todos lo sigan igual, en papel y en la computadora."},{"tipo":"tabla","titulo":"Métodos de archivo","encabezados":["Método","Cómo ordena","Cuándo conviene"],"filas":[["<b>Alfabético</b>","Por apellido o nombre de empresa, de la A a la Z","Expedientes de pacientes, clientes o proveedores"],["<b>Numérico</b>","Por número de folio, expediente o factura","Cuando todo tiene folio consecutivo (facturas, órdenes de compra)"],["<b>Cronológico</b>","Por fecha, del más antiguo al más reciente o al revés","Correspondencia, recibos, estados de cuenta"],["<b>Temático</b>","Por asunto: contratos, recursos humanos, compras, impuestos","Documentos internos de la oficina"],["<b>Mixto</b>","Combina: tema, luego año, luego alfabético","Lo más común en oficinas reales"]]},{"tipo":"pasos","rotulo":"Organiza un archivo desde cero","pasos":["Haz un inventario rápido: qué tipos de documentos hay y cuántos.","Elige el método por tipo de documento (por ejemplo, clientes alfabético y facturas numérico).","Etiqueta carpetas y cajas con letra clara: tema, año y rango (por ejemplo, «Clientes 2026 A–F»).","Crea la misma estructura en la computadora o en la nube, con los mismos nombres.","Escribe las reglas en una hoja y pégala donde todos la vean.","Define cada cuánto se depura: lo que ya no se usa va al archivo muerto con su etiqueta de año."]},{"tipo":"destacado","texto":"<b>¿Cuánto tiempo se guarda cada papel?</b> Depende del documento y de la ley que aplique. Por ejemplo, la documentación contable y fiscal, en general, se conserva <b>5 años</b> según el Código Fiscal de la Federación (art. 30), con excepciones. Antes de destruir cualquier documento, pregunta a tu jefe o al contador cuál es la política del lugar."},{"tipo":"relacionar","rotulo":"¿Qué método conviene?","pares":[["Expedientes de pacientes","Alfabético por apellido"],["Facturas con folio consecutivo","Numérico"],["Estados de cuenta del banco","Cronológico"],["Contratos, compras y recursos humanos","Temático"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La prueba de un buen archivo es que…","ops":["Cualquier persona encuentre un documento en menos de un minuto","Solo tú sepas dónde está todo","Todo esté en una sola caja grande"],"correcta":0,"explica":"Si solo tú encuentras las cosas, el archivo depende de ti y no de un sistema."},{"p":"Conviene que las carpetas digitales…","ops":["Tengan nombres distintos para no confundirse","Estén todas en el escritorio de la computadora","Sigan la misma estructura y nombres que el archivo físico"],"correcta":2},{"p":"Antes de destruir documentos viejos debes…","ops":["Quemarlos sin revisar","Confirmar la política de conservación con tu jefe o el contador","Tirar todo lo que tenga más de un año"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el contrato que apareció en la carpeta de «Varios»</b><br>Un despacho contable en Celaya tardó dos horas en encontrar el contrato de un cliente que el SAT pedía. Estaba en una carpeta llamada «Varios 2», en papel, y en la computadora había tres copias con nombres distintos. Nadie había escrito las reglas del archivo.<br>Un buen archivo permite que cualquiera encuentre un documento en menos de un minuto. Elige un método según el tipo de documento, escribe las reglas y usa la misma estructura en papel y en digital."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué método conviene para expedientes de clientes?","ops":["En «Varios»","Por color de carpeta","Alfabético o numérico por cliente"],"correcta":2,"explica":"El método se elige según cómo se buscan los documentos."},{"p":"¿Por qué usar la misma estructura en papel y en digital?","ops":["Porque se ve bonito","Para que quien busque sepa dónde está en ambos","No importa"],"correcta":1,"explica":"Una sola lógica evita confusiones."},{"p":"Antes de destruir documentos viejos…","ops":["se confirma la política de conservación","se tiran si ocupan espacio","se queman"],"correcta":0,"explica":"Algunos documentos deben conservarse por años."}]},{"tipo":"comparar","titulo":"Cómo se nombra una carpeta","mal":"«Varios 2»","bien":"«Clientes / 0045_Hernández_Construcciones / 2026 / Contratos»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Diseña la estructura de archivo (carpetas y subcarpetas) de una oficina que conozcas, en papel y en digital.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe las cinco reglas de archivo que pegarías junto al archivero para que todos las sigan.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Estructura de archivo","texto":"ESTRUCTURA DE ARCHIVO — [Oficina]\n01_Administración / Contratos · Facturas · Nómina\n02_Clientes / [Número_Nombre] / [Año] / Contratos · Correspondencia\n03_Proveedores / [Nombre] / Cotizaciones · Órdenes de compra\n04_Recursos Humanos / Expedientes (confidencial)\n\nREGLAS\n1. Nada se guarda en «Varios».\n2. Mismas carpetas en papel y en la nube.\n3. [ ]\nConservación: consultar [responsable] antes de destruir.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Un buen archivo permite que cualquiera encuentre un documento en menos de un minuto.","Alfabético, numérico, cronológico, temático o mixto: elige por tipo de documento y escribe las reglas.","La misma estructura en papel y en digital; no destruyas nada sin confirmar la política de conservación."]}],"d-asistente-administrativo-m3-l2":[{"tipo":"texto","texto":"¿Te suena «contrato final», «contrato final 2», «contrato final ahora sí»? Ese desorden hace que se mande la versión equivocada a un cliente. La solución es una <b>regla de nombres</b> que todos usen igual. La más útil empieza con la fecha al revés (año-mes-día), porque así la computadora los ordena solos por fecha."},{"tipo":"plantilla","rotulo":"Regla de nombres de la oficina","texto":"AAAA-MM-DD_Tipo_ClienteOAsunto_vNN\n\nEjemplos:\n2026-03-12_Cotizacion_PapeleraCentro_v01\n2026-03-14_Contrato_HotelLaPaz_v03\n2026-03-20_Minuta_JuntaDireccion_v01\n\nReglas:\n• Sin acentos, sin ñ y sin espacios (usa guion bajo o mayúscula al inicio de cada palabra).\n• Versión con dos dígitos: v01, v02… y «final» solo cuando ya está firmado o enviado.\n• Nada de «nuevo», «bueno» o «este sí».","nota":"Los acentos y espacios a veces causan errores al subir archivos a sistemas o mandarlos por correo."},{"tipo":"comparar","titulo":"La misma carpeta","malTitulo":"Desordenada","mal":"contrato.docx<br>contrato final.docx<br>contrato final (2).docx<br>CONTRATO BUENO jefe.docx","bienTitulo":"Ordenada","bien":"2026-03-10_Contrato_HotelLaPaz_v01.docx<br>2026-03-12_Contrato_HotelLaPaz_v02.docx<br>2026-03-14_Contrato_HotelLaPaz_v03_final.pdf"},{"tipo":"excel","rotulo":"Arma los nombres de archivo con la regla","datos":[["Fecha","Tipo","Cliente o asunto","Versión","Nombre del archivo"],["2026-03-12","Cotizacion","PapeleraCentro","v01",""],["2026-03-14","Contrato","HotelLaPaz","v03",""],["2026-03-20","Minuta","JuntaDireccion","v01",""],["","","","",""],["Documentos tipo Contrato","","","",""],["Largo del primer nombre","","","",""]],"retos":[{"celda":"E2","formula":"=A2&\"_\"&B2&\"_\"&C2&\"_\"&D2","esperado":"2026-03-12_Cotizacion_PapeleraCentro_v01","texto":"<b>E2</b>: une fecha, tipo, cliente y versión con guion bajo entre cada parte. Usa el operador &.","pista":"=A2&\"_\"&B2&\"_\"&C2&\"_\"&D2. El guion bajo va entre comillas porque es texto."},{"celda":"E3","formula":"=CONCATENAR(A3,\"_\",B3,\"_\",C3,\"_\",D3)","esperado":"2026-03-14_Contrato_HotelLaPaz_v03","requiere":"CONCATENAR(","texto":"<b>E3</b>: ahora hazlo con la función CONCATENAR."},{"celda":"E4","formula":"=A4&\"_\"&B4&\"_\"&C4&\"_\"&D4","esperado":"2026-03-20_Minuta_JuntaDireccion_v01","texto":"<b>E4</b>: arma el nombre de la minuta con el método que prefieras."},{"celda":"B6","formula":"=CONTAR.SI(B2:B4,\"Contrato\")","esperado":1,"requiere":"CONTAR.SI(","texto":"<b>B6</b>: cuenta cuántos documentos son de tipo «Contrato»."},{"celda":"B7","formula":"=LARGO(E2)","esperado":40,"requiere":"LARGO(","texto":"<b>B7</b>: ¿cuántos caracteres tiene el nombre de E2? Usa LARGO.","explica":"Con 40 caracteres el nombre es claro y cabe bien en cualquier sistema. Si un nombre pasa de 60 o 70, conviene abreviar el asunto."}]},{"tipo":"completar","rotulo":"Completa la regla","items":[{"frase":"La fecha va al inicio en formato año-mes-___, para que se ordene sola.","resp":["día","dia"]},{"frase":"La segunda versión de un documento se nombra ___.","resp":["v02"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Cuál nombre sigue la regla?","ops":["2026-04-02_Oficio_SecretariaEducacion_v01","oficio nuevo abril.docx","Oficio_02-04-26 final BUENO"],"correcta":0,"explica":"Fecha año-mes-día, tipo, asunto y versión, sin espacios ni acentos."},{"p":"Poner la fecha como 2026-04-02 y no como 02-04-2026 sirve para…","ops":["Que se vea más elegante","Nada, es igual","Que la computadora ordene los archivos por fecha automáticamente"],"correcta":2},{"p":"«final» en el nombre se usa…","ops":["Nunca","Solo cuando el documento ya está firmado o enviado","En cada versión que te parezca buena"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: «presupuesto_final_final_ahora_si.docx»</b><br>En una agencia de publicidad de la Ciudad de México, se envió al cliente el presupuesto equivocado. En la carpeta había «presupuesto_final», «presupuesto_final2», «presupuesto_final_final» y «presupuesto_bueno». Nadie sabía cuál era el último.<br>Regla de nombres: AAAA-MM-DD_Tipo_Asunto_vNN, sin acentos ni espacios. «Final» solo cuando ya se firmó o envió. En hoja de cálculo, & arma los nombres sin errores."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué nombre sigue la regla?","ops":["Presupuesto Cliente Sol (2)","presupuesto final bueno","2026-05-12_Presupuesto_ClienteSol_v03"],"correcta":2,"explica":"Fecha, tipo, asunto y versión con dos dígitos."},{"p":"¿Por qué la fecha al revés (AAAA-MM-DD)?","ops":["Porque así los archivos se ordenan solos por fecha","Porque es más elegante","Porque lo pide el SAT"],"correcta":0,"explica":"El orden alfabético coincide con el cronológico."},{"p":"Para armar el nombre con celdas de fecha, tipo y asunto se usa…","ops":["SUMA","BUSCARV","&, CONCATENAR o TEXTO para la fecha"],"correcta":2,"explica":"Ejemplo: =TEXTO(A2,\"aaaa-mm-dd\")&\"_\"&B2&\"_\"&C2."}]},{"tipo":"comparar","titulo":"Cómo se ve la carpeta","mal":"«presupuesto_final, presupuesto_final2, presupuesto_bueno»","bien":"«2026-05-10_Presupuesto_ClienteSol_v01, …_v02, 2026-05-12_Presupuesto_ClienteSol_v03_final»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Renombra con la regla diez archivos reales o inventados de tu computadora o de una oficina, y escribe la fórmula que armaría esos nombres en una hoja de cálculo.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Regla de nombres y fórmula","texto":"REGLA: AAAA-MM-DD_Tipo_Asunto_vNN\nSin acentos, sin espacios, sin «final» hasta que se firme o envíe.\n\nHOJA DE NOMBRES\nFecha | Tipo | Asunto | Versión | Nombre\n[ ] | [Oficio] | [ ] | [3] | [=TEXTO(A2,\"aaaa-mm-dd\")&\"_\"&B2&\"_\"&C2&\"_v\"&TEXTO(D2,\"00\")]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Regla: AAAA-MM-DD_Tipo_Asunto_vNN, sin acentos ni espacios.","Versiones con dos dígitos; «final» solo cuando ya se firmó o envió.","En hoja de cálculo, & o CONCATENAR arman los nombres y evitan errores."]}],"d-asistente-administrativo-m3-l3":[{"tipo":"texto","texto":"En muchas juntas se habla mucho y se acuerda poco, o se acuerda y luego nadie se acuerda. La <b>minuta</b> resuelve eso: es el registro corto de <b>quién estuvo, qué se decidió, quién hace qué y para cuándo</b>. Tú no tienes que escribir todo lo que se dijo; tienes que capturar los acuerdos."},{"tipo":"tabla","titulo":"Minuta y acta no son lo mismo","encabezados":["","Minuta","Acta"],"filas":[["Para qué","Dar seguimiento a acuerdos de trabajo","Dejar constancia formal de una reunión, a veces con efectos legales"],["Formato","Libre y breve","Más formal; en sociedades o asociaciones puede tener requisitos"],["Firmas","Normalmente no; se envía por correo","Suelen firmarla los asistentes o quien preside"],["Ejemplos","Junta semanal de equipo, reunión con proveedor","Asamblea de accionistas, junta de condóminos, consejo escolar"]],"nota":"Si te piden un acta de asamblea de una sociedad o una asociación civil, pide el formato que usa el abogado o el notario: esas actas tienen requisitos propios."},{"tipo":"plantilla","rotulo":"Formato de minuta","texto":"MINUTA — [Nombre de la junta]\nFecha: [día] · Hora: [inicio]–[fin] · Lugar: [sala o videollamada]\nAsistentes: [nombres y puestos]\nNo asistieron: [nombres]\nRedactó: [tu nombre]\n\nTEMAS\n1. [Tema]\n2. [Tema]\n\nACUERDOS\n| # | Acuerdo | Responsable | Fecha límite |\n| 1 | [Qué se hará, en concreto] | [Nombre] | [Fecha] |\n| 2 | ... | ... | ... |\n\nPENDIENTES DE LA JUNTA ANTERIOR\n[Acuerdo] — [cumplido / en proceso / atrasado]\n\nPRÓXIMA JUNTA: [fecha y hora]","nota":"Manda la minuta el mismo día o a más tardar al día siguiente, cuando todos todavía recuerdan lo que se dijo."},{"tipo":"comparar","titulo":"Cómo escribir un acuerdo","malTitulo":"Vago","mal":"«Se verá lo de la papelería.»","bienTitulo":"Concreto","bien":"«Laura pedirá tres cotizaciones de papelería y las enviará a la Lic. Herrera el viernes 15 a las 12:00.»"},{"tipo":"ordenar","rotulo":"Ordena el acuerdo","items":[{"frase":"Jorge enviará el contrato firmado el martes"},{"frase":"Laura reservará la sala para el jueves"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un acuerdo bien escrito tiene…","ops":["Qué se hará, responsable y fecha límite","Solo el tema","Todo lo que dijo cada persona"],"correcta":0,"explica":"Si falta el responsable o la fecha, el acuerdo casi siempre se pierde."},{"p":"La asamblea anual de accionistas de una S.A. se documenta con…","ops":["Un recado","Una minuta informal por WhatsApp","Un acta con sus requisitos formales"],"correcta":2},{"p":"La minuta conviene enviarla…","ops":["Solo si alguien la pide","El mismo día o al día siguiente","Un mes después"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la junta de la que nadie recordaba nada</b><br>Una escuela en San Luis Potosí tuvo una junta con padres para organizar el festival. Hubo muchas ideas, pero la minuta decía: «Se platicó del festival. Se acordó organizarlo bien». Dos semanas después nadie había rentado sillas y cada quien creía que le tocaba a otro.<br>Minuta: quién estuvo, qué se acordó, quién lo hace y para cuándo. Un acuerdo concreto es acción + responsable + fecha límite."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"«Se acordó organizarlo bien» es…","ops":["un acta formal","un buen acuerdo","un acuerdo vago, sin acción, responsable ni fecha"],"correcta":2,"explica":"No se puede verificar."},{"p":"Un acuerdo concreto sería…","ops":["«Ver lo de las sillas»","«Rentar 200 sillas: Sra. López, antes del 10 de junio»","«Alguien consigue sillas»"],"correcta":1,"explica":"Acción + responsable + fecha."},{"p":"¿En qué se distingue un acta de una minuta?","ops":["Son lo mismo","La minuta es más larga","El acta es más formal y a veces tiene requisitos legales"],"correcta":2,"explica":"Pide el formato de acta a quien corresponda."}]},{"tipo":"comparar","titulo":"Cómo se escribe el acuerdo","mal":"«Se platicó del festival. Se acordó organizarlo bien.»","bien":"«Acuerdo 1: rentar 200 sillas — Sra. López — 10 de junio. Acuerdo 2: programa del festival — Mtra. Díaz — 5 de junio.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe la minuta de una junta real o imaginaria (de trabajo, escuela o vecinos) con al menos cinco acuerdos concretos.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe el mensaje con el que enviarías esa minuta el mismo día a los asistentes.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Minuta de junta","texto":"MINUTA — [Tema]\nFecha: [ ]   Hora: [ ]   Lugar o liga: [ ]\nAsistentes: [ ]\nObjetivo de la junta: [ ]\n\nTEMAS TRATADOS (resumen breve)\n1. [ ]\n\nACUERDOS\nNo. | Acción | Responsable | Fecha límite\n1 | [ ] | [ ] | [ ]\n\nPróxima junta: [ ]   Elaboró: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Minuta: quién estuvo, qué se acordó, quién lo hace y para cuándo.","Acuerdo concreto = acción + responsable + fecha límite.","El acta es formal y a veces tiene requisitos legales; pide el formato a quien corresponda."]}],"d-asistente-administrativo-m3-l4":[{"tipo":"tabla","titulo":"Tres documentos que vas a redactar","encabezados":["Documento","A quién va","Para qué"],"filas":[["<b>Oficio</b>","Fuera de la organización, sobre todo a dependencias de gobierno, escuelas u otras instituciones","Pedir, informar o responder algo de forma oficial; lleva número de folio"],["<b>Memorándum</b>","Dentro de la organización, de un área a otra","Avisos, instrucciones o recordatorios internos, breves"],["<b>Circular</b>","A muchas personas a la vez (todo el personal, todas las familias)","Avisos generales: horarios, días inhábiles, reglas nuevas"]]},{"tipo":"plantilla","rotulo":"Oficio","texto":"[Logotipo y nombre de la empresa]\nOficio No. DH/015/2026\nAsunto: Solicitud de constancia de estudios\n\nGuadalajara, Jalisco, a 12 de marzo de 2026\n\n[Nombre del destinatario]\n[Cargo]\n[Institución]\nP r e s e n t e\n\nPor medio del presente, me permito solicitar [qué pides, en concreto], con el fin de [para qué].\n\nPara cualquier aclaración, quedo a sus órdenes en el teléfono [número] o en el correo [correo].\n\nSin otro particular, le envío un cordial saludo.\n\nAtentamente\n\n[Firma]\n[Nombre de quien firma]\n[Cargo]\n\nc.c.p. [Nombre y cargo de quien recibe copia]","nota":"Lleva un control de folios de oficios en una hoja: número, fecha, destinatario, asunto y si ya respondieron."},{"tipo":"pasos","rotulo":"Organiza una junta","pasos":["Confirma con tu jefe objetivo, asistentes, duración y si es presencial o en línea.","Revisa la disponibilidad de todos en el calendario compartido y propone dos horarios.","Envía la invitación con asunto claro, orden del día, lugar o liga y documentos a revisar.","Un día antes: confirma asistencia, reserva la sala, prueba proyector y liga, prepara agua y copias.","Durante la junta: toma la minuta.","Después: envía la minuta y agenda los seguimientos de cada acuerdo."]},{"tipo":"lista","items":["<b>Agenda del jefe:</b> deja 15 minutos entre citas para traslados o retrasos, bloquea tiempo para su trabajo sin interrupciones y confirma las citas externas un día antes.","<b>Viaje de trabajo:</b> vuelo o autobús, hotel cerca del lugar de las citas, transporte al llegar, itinerario en un solo documento, copia de reservaciones en su celular y en tu correo, viáticos autorizados y datos de facturación para pedir facturas.","<b>Itinerario:</b> hora por hora, con direcciones, teléfonos de contacto y número de confirmación de cada reservación."]},{"tipo":"relacionar","rotulo":"¿Qué documento usas?","pares":[["Pedirle a la Secretaría de Educación estatal una constancia","Oficio"],["Avisar a Contabilidad que cambió el día de entrega de facturas","Memorándum"],["Informar a todas las familias que el viernes no hay clases","Circular"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Al acomodar la agenda de tu jefe conviene dejar entre citas…","ops":["Unos 15 minutos para traslados o retrasos","Ningún espacio, para aprovechar el día","Dos horas"],"correcta":0},{"p":"En la invitación a una junta no debe faltar…","ops":["El chisme de la oficina","La minuta de la junta","El orden del día y el lugar o la liga"],"correcta":2},{"p":"En un viaje de trabajo, pedir la factura del hotel con los datos de la empresa sirve para…","ops":["Nada, basta con el ticket","Comprobar el gasto de viáticos","Obtener puntos del hotel"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el jefe con tres juntas a la misma hora</b><br>El gerente de una distribuidora en Chihuahua llegó a su oficina y tenía una junta con un cliente, otra con su equipo y una llamada con el banco, las tres a las 10. Además, debía volar a Monterrey a las 2 y nadie había reservado hotel. Su asistente anotaba todo en una libreta y en su celular, por separado.<br>Agenda con márgenes de 15 minutos; juntas con objetivo, invitación, confirmación y minuta; viajes con itinerario, reservaciones y facturas. Oficio hacia fuera con folio; memorándum hacia dentro."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué causó el empalme de juntas?","ops":["Llevar la agenda en varios lugares sin uno central","El jefe","Los clientes"],"correcta":0,"explica":"Una sola agenda compartida evita empalmes."},{"p":"¿Cuándo se confirma una junta?","ops":["No se confirma","Un día antes","Una semana antes"],"correcta":1,"explica":"La confirmación reduce cancelaciones de último momento."},{"p":"Para avisar al personal un cambio de horario interno se usa…","ops":["un memorándum o circular","una factura","un oficio con folio a otra empresa"],"correcta":0,"explica":"El memorándum es comunicación interna."}]},{"tipo":"comparar","titulo":"Cómo se prepara el viaje","mal":"«Ya tiene su vuelo, lo demás lo ve allá.»","bien":"«Itinerario: vuelo 2:10 p. m. (confirmado), traslado al hotel (reservado, factura a nombre de la empresa), junta 5 p. m. con dirección y contacto. Regreso el jueves 9 a. m.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Organiza la agenda de un día de un jefe con cinco compromisos, dejando márgenes, y escribe el correo de invitación a una de las juntas con su orden del día.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Redacta un memorándum interno y un oficio externo sobre el mismo tema (por ejemplo, cambio de domicilio de la empresa).","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Itinerario de viaje y oficio","texto":"ITINERARIO — [Nombre] — [Destino]\nIda: [aerolínea, vuelo, hora, confirmación]\nHotel: [nombre, dirección, confirmación, facturar a: ]\nTraslados: [ ]\nAgenda: [hora — reunión — contacto — dirección]\nRegreso: [ ]\nViáticos autorizados: $[ ]\n\nOFICIO\nFolio: [ ]  Fecha: [ ]\nAsunto: [ ]\n[Destinatario, cargo, empresa]\n[Cuerpo breve]\nAtentamente, [firma, cargo]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Oficio hacia fuera con folio, memorándum hacia dentro y circular para muchos.","Juntas: objetivo, invitación con orden del día, confirmación un día antes y minuta al terminar.","Agenda con márgenes de 15 minutos; viajes con itinerario, reservaciones y facturas."]}],"d-asistente-administrativo-m3-lab":[{"tipo":"destacado","texto":"Entras como asistente a <b>Constructora Ruiz</b>, en Querétaro. El archivo físico está en cajas, la carpeta compartida tiene 900 archivos con nombres como «doc1» o «final2», las juntas no tienen minuta y el director tiene citas empalmadas cada semana."},{"tipo":"texto","texto":"<p><b>Escena 1 — El archivo.</b> Hay contratos de obra, facturas, planos, expedientes de personal y correspondencia.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe la estructura de carpetas (física y digital) y el método de cada tipo de documento.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — Los nombres.</b> Tienes 900 archivos mal nombrados.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe la regla de nombres y cómo organizarías el trabajo de renombrar sin detener la oficina.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — Las juntas.</b> El director quiere que los acuerdos se cumplan.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Escribe el proceso de juntas: invitación, confirmación, minuta y seguimiento de acuerdos.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — La agenda.</b> El director usa su celular, tú una libreta y el socio otro calendario.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Propón cómo unificar la agenda y las reglas para agendar.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"¿Qué documentos van con acceso restringido?","ops":["Los expedientes de personal","Los planos públicos","El directorio"],"correcta":0,"explica":"Contienen datos personales."},{"p":"Para 900 archivos, conviene…","ops":["dejarlos así","renombrar todo en un día","empezar por los de uso frecuente y aplicar la regla a todo lo nuevo desde hoy"],"correcta":2,"explica":"Orden progresivo sin detener el trabajo."},{"p":"Un acuerdo sin fecha…","ops":["es suficiente","no se puede verificar; debe llevar fecha límite","es un acta"],"correcta":1,"explica":"Acción + responsable + fecha."}]},{"tipo":"plantilla","rotulo":"Plan de orden en 30 días","texto":"PLAN DE ORDEN — [Oficina]\nSemana 1: estructura de carpetas y reglas escritas\nSemana 2: regla de nombres y archivos frecuentes\nSemana 3: agenda única y reglas para agendar\nSemana 4: proceso de juntas y seguimiento de acuerdos\nIndicador: tiempo para encontrar un documento [antes / después]","nota":"Cópiala y úsala en tu trabajo."}],"d-asistente-administrativo-m4-l1":[{"tipo":"texto","texto":"La <b>caja chica</b> es un fondo de efectivo para gastos pequeños y urgentes: garrafones, mensajería, copias, un taxi a la notaría. Casi siempre funciona como <b>fondo fijo</b>: la empresa te entrega, por ejemplo, $3,000. Cada gasto se paga con ese dinero y se guarda su comprobante. En todo momento se cumple una regla: <b>efectivo + comprobantes = fondo fijo</b>. Cuando el efectivo baja, entregas los comprobantes y te <b>reponen</b> exactamente lo gastado."},{"tipo":"pasos","rotulo":"Reglas de una caja chica sana","pasos":["Una sola persona responsable, con la caja bajo llave.","Monto máximo por gasto (por ejemplo, $500); arriba de eso va por requisición.","Todo gasto con comprobante: factura a nombre de la empresa de preferencia, o ticket o vale firmado si no hay otra opción.","Anota cada gasto el mismo día en la hoja de control: fecha, concepto, comprobante e importe.","Haz un <b>arqueo</b> (contar el efectivo y comparar) cada semana y cada vez que pidas reposición.","Nunca prestes dinero de la caja ni la mezcles con tu dinero personal."]},{"tipo":"excel","rotulo":"Arqueo semanal de caja chica: Despacho Herrera","datos":[["Fecha","Concepto","Comprobante","Importe","","Arqueo","Importe"],["01/09","Garrafones de agua","Ticket",180,"","Fondo fijo",3000],["02/09","Papel para impresora","Factura",395,"","Total gastado",""],["03/09","Mensajería a cliente","Factura",260,"","Gastos con factura",""],["04/09","Café y galletas para junta","Ticket",215,"","Debe haber en efectivo",""],["05/09","Taxi a notaría","Vale firmado",150,"","Efectivo contado",1392],["08/09","Copias y engargolado","Factura",120,"","Diferencia",""],["09/09","Focos para recepción","Factura",238,"","Resultado",""]],"retos":[{"celda":"G3","formula":"=SUMA(D2:D8)","esperado":1558,"requiere":"SUMA(","texto":"<b>G3</b>: suma todos los gastos de la semana."},{"celda":"G4","formula":"=SUMAR.SI(C2:C8,\"Factura\",D2:D8)","esperado":1013,"requiere":"SUMAR.SI(","texto":"<b>G4</b>: suma solo los gastos que tienen factura. Usa SUMAR.SI con la columna de comprobante.","pista":"=SUMAR.SI(C2:C8,\"Factura\",D2:D8): dónde buscas, qué buscas y qué sumas."},{"celda":"G5","formula":"=G2-G3","esperado":1442,"texto":"<b>G5</b>: ¿cuánto efectivo debería haber? Fondo fijo menos total gastado."},{"celda":"G7","formula":"=G6-G5","esperado":-50,"texto":"<b>G7</b>: diferencia: efectivo contado menos lo que debe haber."},{"celda":"G8","formula":"=SI(G7=0,\"Cuadra\",SI(G7<0,\"Faltante\",\"Sobrante\"))","esperado":"Faltante","requiere":"SI(","texto":"<b>G8</b>: con SI anidados: si la diferencia es 0, «Cuadra»; si es negativa, «Faltante»; si no, «Sobrante».","explica":"Faltan $50. Antes de reportarlo, busca un comprobante que no anotaste o un gasto sin registrar. Si no aparece, se reporta de inmediato y por escrito: nunca lo «completes» con tu dinero sin decir nada."}]},{"tipo":"destacado","texto":"<b>¿Factura o ticket?</b> Para la empresa, los gastos con <b>factura (CFDI) a su nombre</b> son los que su contador puede usar para impuestos. Un ticket o un vale sirven para control interno, pero muchas veces no le sirven al contador. Siempre que se pueda, pide factura con los datos de la empresa."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En una caja chica de fondo fijo, siempre se cumple que…","ops":["Efectivo más comprobantes es igual al fondo","El efectivo siempre es igual al fondo","Los comprobantes se tiran al reponer"],"correcta":0,"explica":"Por eso el arqueo es tan sencillo: cuentas efectivo, sumas comprobantes y comparas."},{"p":"El fondo es de $2,000, gastaste $1,250 con comprobantes y cuentas $700 en efectivo. Hay…","ops":["Un sobrante de $50","Cuadra exacto","Un faltante de $50"],"correcta":2},{"p":"Si te falta dinero en el arqueo, lo correcto es…","ops":["Esperar a ver si aparece el próximo mes","Revisar comprobantes y, si no aparece, reportarlo por escrito","Ponerlo de tu bolsa sin decir nada"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la caja chica que nunca cuadraba</b><br>En una clínica veterinaria de Mazatlán, la caja chica tiene un fondo de $3,000. Cada viernes falta dinero y nadie sabe por qué: hay vales sin firma, tickets sin fecha y préstamos «para el camión» que no se anotan.<br>Caja chica de fondo fijo: efectivo + comprobantes = fondo. El arqueo cuenta el efectivo, suma los gastos y compara. Cualquier diferencia se reporta por escrito."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"Fondo $3,000; efectivo $1,150; comprobantes $1,700. El resultado es…","ops":["sobrante de $150","cuadra","faltante de $150"],"correcta":2,"explica":"1,150 + 1,700 = 2,850; faltan 150."},{"p":"¿Qué hacer con los préstamos «para el camión»?","ops":["Olvidarlos","Anotarlos de memoria","No se prestan de la caja chica; si la política lo permite, se documentan con vale firmado"],"correcta":2,"explica":"Todo lo que sale debe tener comprobante."},{"p":"¿Qué comprobante es mejor?","ops":["Factura a nombre de la empresa","Ticket sin fecha","Nota a mano sin firma"],"correcta":0,"explica":"La factura es el comprobante más sólido."}]},{"tipo":"comparar","titulo":"Cómo se reporta la diferencia","mal":"«Faltan como 150, ahí lo repongo yo.»","bien":"«Arqueo del viernes: faltante de $150. Hay dos vales sin firma por ese monto. Anexo el detalle y propongo firmar todo vale al momento.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe las reglas de uso de una caja chica para una oficina pequeña: quién la maneja, qué se puede pagar, qué comprobantes se aceptan y cada cuánto se arquea.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Arqueo de caja chica","texto":"ARQUEO — [Fecha]\nFondo fijo: $[3,000]\nEfectivo contado (billetes y monedas): $[ ]\nComprobantes: [=SUMA(gastos)]\nTotal: [=B2+B3]\nResultado: [=SI(B4=B1,\"Cuadra\",SI(B4<B1,\"Faltante de \"&B1-B4,\"Sobrante de \"&B4-B1))]\n\nGastos: Fecha | Concepto | Monto | ¿Factura? | Firma\nFirmas del arqueo: [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Caja chica de fondo fijo: efectivo + comprobantes = fondo.","Arqueo: cuenta el efectivo, suma los gastos y compara; SI te dice si cuadra, falta o sobra.","Pide factura a nombre de la empresa siempre que se pueda y reporta cualquier diferencia por escrito."]}],"d-asistente-administrativo-m4-l2":[{"tipo":"texto","texto":"Los <b>viáticos</b> son el dinero para los gastos de un viaje de trabajo: transporte, hospedaje y alimentos. Normalmente se entrega un <b>anticipo</b> y, al regresar, se <b>comprueba</b> con facturas. Si se gastó menos, se devuelve la diferencia; si se gastó más y estaba autorizado, se reembolsa al empleado. Como asistente, muchas veces tú armas la comprobación de tu jefe o de todo el equipo."},{"tipo":"lista","items":["<b>Antes del viaje:</b> solicitud de viáticos con destino, fechas, motivo y monto estimado; autorización por escrito.","<b>Durante:</b> pedir factura de cada gasto con los datos fiscales de la empresa (llévalos en el celular).","<b>Después:</b> reporte de gastos con facturas, dentro del plazo que marque la política (por ejemplo, 5 días hábiles)."]},{"tipo":"excel","rotulo":"Comprobación de viáticos: viaje Guadalajara–Monterrey, 2 días","datos":[["Concepto","Categoría","Importe","¿Con factura?","","Resumen","Importe"],["Autobús GDL–MTY","Transporte",1250,"Sí","","Transporte",""],["Hotel 2 noches","Hospedaje",2400,"Sí","","Hospedaje",""],["Comida día 1","Alimentos",540,"Sí","","Alimentos",""],["Cena día 1","Alimentos",380,"No","","Total gastado",""],["Comida día 2","Alimentos",460,"Sí","","Comprobado con factura",""],["Taxi a oficina del cliente","Transporte",210,"Sí","","Tope de alimentos (2 días × $600)",1200],["Autobús MTY–GDL","Transporte",1250,"Sí","","Alimentos contra tope",""],["","","","","","Anticipo entregado",6000],["","","","","","Saldo",""],["","","","","","Qué procede",""]],"retos":[{"celda":"G2","formula":"=SUMAR.SI($B$2:$B$8,F2,$C$2:$C$8)","esperado":2710,"requiere":"SUMAR.SI(","texto":"<b>G2</b>: suma todo lo de categoría «Transporte» con SUMAR.SI. Fija los rangos con $ para copiarla hacia abajo.","pista":"=SUMAR.SI($B$2:$B$8,F2,$C$2:$C$8)"},{"celda":"G3","formula":"=SUMAR.SI($B$2:$B$8,F3,$C$2:$C$8)","esperado":2400,"requiere":"SUMAR.SI(","texto":"<b>G3</b>: suma el hospedaje."},{"celda":"G4","formula":"=SUMAR.SI($B$2:$B$8,F4,$C$2:$C$8)","esperado":1380,"requiere":"SUMAR.SI(","texto":"<b>G4</b>: suma los alimentos."},{"celda":"G5","formula":"=SUMA(C2:C8)","esperado":6490,"requiere":"SUMA(","texto":"<b>G5</b>: total gastado en el viaje."},{"celda":"G6","formula":"=SUMAR.SI(D2:D8,\"Sí\",C2:C8)","esperado":6110,"requiere":"SUMAR.SI(","texto":"<b>G6</b>: suma solo lo que tiene factura (columna D dice «Sí»)."},{"celda":"G8","formula":"=SI(G4>G7,\"Excede tope\",\"Dentro del tope\")","esperado":"Excede tope","requiere":"SI(","texto":"<b>G8</b>: si los alimentos pasan del tope de G7, escribe «Excede tope»; si no, «Dentro del tope»."},{"celda":"G10","formula":"=G9-G5","esperado":-490,"texto":"<b>G10</b>: saldo: anticipo menos total gastado."},{"celda":"G11","formula":"=SI(G10<0,\"Reembolsar al empleado\",\"Devolver a la empresa\")","esperado":"Reembolsar al empleado","requiere":"SI(","texto":"<b>G11</b>: si el saldo es negativo, «Reembolsar al empleado»; si no, «Devolver a la empresa».","explica":"Se gastaron $490 más que el anticipo, pero los alimentos pasaron $180 del tope y la cena de $380 no tiene factura. Con estos datos el jefe decide qué se autoriza antes de reembolsar."}]},{"tipo":"destacado","texto":"El tope de $600 diarios de este ejercicio es una <b>política interna</b> de ejemplo. Aparte, la Ley del ISR fija límites y requisitos para que los viáticos sean deducibles para la empresa; esos los revisa el contador. Tú asegúrate de que cada gasto tenga factura y de que el reporte esté completo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si el anticipo fue de $4,000 y se gastaron $3,650 comprobados, el empleado…","ops":["Devuelve $350 a la empresa","Recibe $350 de reembolso","No hace nada"],"correcta":0,"explica":"Saldo positivo: sobró dinero del anticipo."},{"p":"=SUMAR.SI(B2:B8,\"Hospedaje\",C2:C8) suma…","ops":["Cuántos renglones dicen Hospedaje","Toda la columna C","Los importes de la columna C cuya categoría es Hospedaje"],"correcta":2},{"p":"Durante el viaje conviene llevar en el celular…","ops":["Solo los boletos de regreso","Los datos fiscales de la empresa para pedir facturas","La contraseña bancaria de la empresa"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: los viáticos comprobados con servilletas</b><br>Un vendedor de una empresa de agroquímicos en Culiacán regresó de una gira de cinco días. Para comprobar sus gastos trajo tickets de gasolina, dos facturas y varias notas escritas en servilletas. Pidió que le reembolsaran $2,300 más de lo autorizado.<br>Viáticos: solicitud autorizada, anticipo, facturas durante el viaje y comprobación al regresar. SUMAR.SI suma por categoría o por «con factura»; SI revisa topes."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuándo se piden las facturas?","ops":["Al regresar","Nunca","Durante el viaje, en cada gasto"],"correcta":2,"explica":"Después es difícil conseguirlas."},{"p":"Si el anticipo fue $6,000 y comprobó $7,400 autorizados, la empresa…","ops":["le cobra $1,400","no hace nada","le debe $1,400"],"correcta":2,"explica":"Comprobó más de lo que recibió, dentro de lo autorizado."},{"p":"Los límites fiscales de deducción…","ops":["no existen","los revisa el contador; tú cuidas que todo esté comprobado","los decides tú"],"correcta":1,"explica":"Tu trabajo es que la comprobación esté completa."}]},{"tipo":"comparar","titulo":"Cómo se entrega la comprobación","mal":"«Aquí están mis papelitos, me deben como $2,300.»","bien":"«Comprobación de la gira a Sinaloa: anticipo $6,000, gastos con factura $7,100, sin factura $300. Excede el tope de alimentos en $200; anexo la justificación.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Arma la comprobación de viáticos de un viaje imaginario de tres días con al menos ocho gastos, y calcula quién le debe a quién.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe la política breve de viáticos que propondrías a una empresa pequeña.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Comprobación de viáticos","texto":"COMPROBACIÓN DE VIÁTICOS\nViajero: [ ]  Destino: [ ]  Fechas: [ ]  Anticipo: $[ ]\nFecha | Concepto | Categoría | Monto | ¿Factura?\nTotal por categoría: [=SUMAR.SI(C:C,\"Alimentos\",D:D)]\nTotal con factura: [=SUMAR.SI(E:E,\"Sí\",D:D)]\nTope de alimentos: $[ ] → [=SI(total>tope,\"Excede\",\"OK\")]\nDiferencia: [=anticipo-total] → [=SI(dif<0,\"La empresa reembolsa\",\"El viajero devuelve\")]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Viáticos: solicitud autorizada, anticipo, facturas durante el viaje y comprobación al regresar.","SUMAR.SI suma por categoría o por «con factura»; SI revisa topes y quién le paga a quién.","Los límites fiscales de deducción los revisa el contador; tu trabajo es que todo esté comprobado."]}],"d-asistente-administrativo-m4-l3":[{"tipo":"texto","texto":"En una oficina ordenada nadie compra «porque sí». Hay un flujo que protege el dinero de la empresa y evita que se acabe el tóner justo el día de la entrega. Y para saber <b>cuándo</b> pedir, se lleva un inventario sencillo con un <b>mínimo</b> (punto de reorden) para cada artículo."},{"tipo":"ordenar","rotulo":"Ordena el flujo de una compra","items":[{"frase":"Requisición cotizaciones orden de compra recepción factura pago"},{"frase":"Primero se autoriza y después se compra"}]},{"tipo":"tabla","titulo":"Del pedido al pago","encabezados":["Paso","Documento","Quién"],"filas":[["1. Pedir","<b>Requisición</b>: qué se necesita, cuánto y para qué","Quien necesita la compra"],["2. Comparar","Tres <b>cotizaciones</b> de proveedores, si la política lo pide","Asistente o compras"],["3. Autorizar y pedir","<b>Orden de compra</b> con folio, proveedor, cantidades, precio y condiciones","Quien autoriza"],["4. Recibir","Revisar que llegue lo pedido, en cantidad y estado; firmar de recibido","Asistente o almacén"],["5. Pagar","<b>Factura</b> del proveedor que coincida con la orden de compra","Administración"]]},{"tipo":"excel","rotulo":"Inventario de papelería: Clínica San Rafael","datos":[["Artículo","Inicial","Entradas","Salidas","Existencia","Mínimo","Estado"],["Hojas carta (paquete de 500)",12,10,15,"",8,""],["Plumas azules (caja de 12)",6,0,4,"",3,""],["Tóner de impresora",3,2,2,"",2,""],["Folders carta (paquete de 100)",4,0,3,1,2,"Pedir"],["Notas adhesivas (bloc)",20,0,6,14,10,"OK"],["","","","","","",""],["Artículos por pedir","","","","","",""]],"retos":[{"celda":"E2","formula":"=B2+C2-D2","esperado":7,"texto":"<b>E2</b>: existencia = inicial + entradas − salidas."},{"celda":"G2","formula":"=SI(E2<=F2,\"Pedir\",\"OK\")","esperado":"Pedir","requiere":"SI(","texto":"<b>G2</b>: si la existencia es menor o igual al mínimo, «Pedir»; si no, «OK».","pista":"=SI(E2<=F2,\"Pedir\",\"OK\")"},{"celda":"E3","formula":"=B3+C3-D3","esperado":2,"texto":"<b>E3</b>: existencia de plumas."},{"celda":"G3","formula":"=SI(E3<=F3,\"Pedir\",\"OK\")","esperado":"Pedir","requiere":"SI(","texto":"<b>G3</b>: estado de las plumas."},{"celda":"E4","formula":"=B4+C4-D4","esperado":3,"texto":"<b>E4</b>: existencia de tóner."},{"celda":"G4","formula":"=SI(E4<=F4,\"Pedir\",\"OK\")","esperado":"OK","requiere":"SI(","texto":"<b>G4</b>: estado del tóner."},{"celda":"B8","formula":"=CONTAR.SI(G2:G6,\"Pedir\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>B8</b>: cuenta cuántos artículos hay que pedir.","explica":"Tres artículos llegaron al mínimo. Con esta lista armas una sola requisición en lugar de tres compras sueltas."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El documento con el que alguien pide internamente que se compre algo es…","ops":["La requisición","La factura","El arqueo"],"correcta":0,"explica":"La orden de compra viene después, cuando ya se autorizó y se eligió proveedor."},{"p":"Tenías 10 cajas, entraron 5 y salieron 9. La existencia es…","ops":["24","14","6"],"correcta":2},{"p":"Antes de pasar una factura a pago conviene revisar que…","ops":["Sea del proveedor más barato","Coincida con la orden de compra y con lo que se recibió","Tenga logotipo a color"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: sin hojas para imprimir el día de la auditoría</b><br>En una empresa de seguridad privada en Querétaro se acabaron las hojas y el tóner el día de la auditoría del cliente. Nadie llevaba inventario de papelería: compraban «cuando se acababa», con el primer proveedor que contestara y sin orden de compra. A fin de mes, además, llegó una factura por material que nunca recibieron.<br>Flujo de compra: requisición, cotizaciones, orden de compra, recepción, factura y pago. Existencia = inicial + entradas − salidas; con SI marcas qué llegó al mínimo."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué evita quedarse sin tóner?","ops":["Pedir cuando se acaba","Comprar mucho de una vez","Un punto de reorden: cuando la existencia llega al mínimo, se pide"],"correcta":2,"explica":"El mínimo cubre el tiempo que tarda en llegar."},{"p":"¿Qué documento prueba lo que se pidió?","ops":["La cotización","La orden de compra","El recado"],"correcta":1,"explica":"La orden de compra es el compromiso formal."},{"p":"La factura por material que no llegó…","ops":["se paga para no quedar mal","se tira","no se paga hasta revisarla contra la orden de compra y la recepción"],"correcta":2,"explica":"Se compara orden, recepción y factura."}]},{"tipo":"comparar","titulo":"Cómo se compra","mal":"«¡Se acabó el tóner! Compren donde sea.»","bien":"«El tóner llegó a su mínimo de 2. Mandé requisición con tres cotizaciones; con la aprobada emito orden de compra y al recibir reviso contra la orden.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Arma el inventario de papelería de una oficina con diez artículos, su mínimo y la fórmula que marca qué pedir. Escribe cómo sería el flujo de compra de uno de ellos.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Inventario de papelería","texto":"INVENTARIO — [Mes]\nArtículo | Inicial | Entradas | Salidas | Existencia | Mínimo | ¿Pedir?\nHojas carta (paquete) | [ ] | [ ] | [ ] | [=B2+C2-D2] | [5] | [=SI(E2<=F2,\"Pedir\",\"\")]\nTóner | [ ] | [ ] | [ ] | [ ] | [2] | [ ]\nArtículos por pedir: [=CONTAR.SI(G:G,\"Pedir\")]\n\nFLUJO: requisición → 3 cotizaciones → orden de compra → recepción → factura → pago","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Flujo: requisición, cotizaciones, orden de compra, recepción, factura y pago.","Existencia = inicial + entradas − salidas; con SI marcas qué llegó al mínimo.","CONTAR.SI junta lo que hay que pedir en una sola requisición."]}],"d-asistente-administrativo-m4-l4":[{"tipo":"texto","texto":"Cuando un proveedor le factura a tu empresa, tú puedes detectar errores antes de que lleguen al contador. En la versión 4.0 del CFDI, obligatoria desde 2023, la factura debe traer los datos del <b>receptor</b> (tu empresa) tal como aparecen en su <b>constancia de situación fiscal</b>. Si algo no coincide, se le pide al proveedor que <b>cancele y vuelva a emitir</b>. No necesitas saber de impuestos para esta revisión: solo comparar con cuidado."},{"tipo":"tabla","titulo":"Qué revisar del receptor","encabezados":["Dato","Qué debe decir","Error común"],"filas":[["<b>RFC</b>","El de la empresa, exacto. Persona moral: 12 caracteres; persona física: 13","Una letra o número cambiado"],["<b>Nombre o razón social</b>","Igual que en la constancia, sin el régimen de capital (sin «S.A. de C.V.»)","Agregar «S.A. de C.V.» o abreviar el nombre"],["<b>Código postal</b>","El del domicilio fiscal que marca la constancia","Poner el CP de la sucursal o de otra oficina"],["<b>Régimen fiscal</b>","La clave del régimen del receptor, por ejemplo 601 (General de Ley Personas Morales) o 612 (Actividades Empresariales y Profesionales)","Poner el régimen del proveedor en lugar del de la empresa"],["<b>Uso del CFDI</b>","El que indique la empresa, por ejemplo G01 (adquisición de mercancías) o G03 (gastos en general)","Dejar S01 (sin efectos fiscales) cuando la empresa sí lo necesita para su contabilidad"]],"nota":"Las claves de régimen y uso vienen de los catálogos del SAT. Tu empresa debe darte por escrito cuál uso pedir en cada tipo de compra; si dudas, pregunta al contador."},{"tipo":"excel","rotulo":"Revisión de factura de papelería: Comercializadora El Mirador","datos":[["Dato","Correcto (constancia y política)","Factura recibida","¿Coincide?"],["RFC","CEM190312AB4","CEM190312AB4",""],["Nombre o razón social","COMERCIALIZADORA EL MIRADOR","COMERCIALIZADORA EL MIRADOR SA DE CV",""],["Código postal",44160,44160,"OK"],["Régimen fiscal","601","601","OK"],["Uso del CFDI","G03","S01",""],["","","",""],["Datos por corregir","","",""],["Tipo de persona","","",""]],"retos":[{"celda":"D2","formula":"=SI(B2=C2,\"OK\",\"Revisar\")","esperado":"OK","requiere":"SI(","texto":"<b>D2</b>: compara el RFC correcto con el de la factura: «OK» si son iguales, «Revisar» si no."},{"celda":"D3","formula":"=SI(B3=C3,\"OK\",\"Revisar\")","esperado":"Revisar","requiere":"SI(","texto":"<b>D3</b>: compara el nombre.","explica":"En CFDI 4.0 el nombre del receptor se escribe como en la constancia, sin «SA DE CV»."},{"celda":"D6","formula":"=SI(B6=C6,\"OK\",\"Revisar\")","esperado":"Revisar","requiere":"SI(","texto":"<b>D6</b>: compara el uso del CFDI."},{"celda":"B8","formula":"=CONTAR.SI(D2:D6,\"Revisar\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>B8</b>: cuenta cuántos datos hay que pedir que se corrijan."},{"celda":"B9","formula":"=SI(LARGO(B2)=12,\"Persona moral\",\"Persona física\")","esperado":"Persona moral","requiere":"LARGO(","texto":"<b>B9</b>: con LARGO revisa cuántos caracteres tiene el RFC: si son 12, «Persona moral»; si no, «Persona física»."}]},{"tipo":"plantilla","rotulo":"Correo para pedir corrección de una factura","texto":"Asunto: Solicitud de corrección de factura [serie y folio] — [nombre de tu empresa]\n\nBuen día, [nombre]:\n\nRecibimos la factura [serie y folio] del [fecha] por $[importe]. Al revisarla encontramos lo siguiente:\n\n• Nombre del receptor: aparece «[como viene]»; debe ser «[como dice la constancia]».\n• Uso del CFDI: aparece [clave]; debe ser [clave].\n\nLes pedimos cancelarla y emitir una nueva con los datos correctos. Adjunto nuestra constancia de situación fiscal para su referencia.\n\nGracias por su apoyo.\n\n[Nombre, puesto, empresa y teléfono]","nota":"Para confirmar que una factura existe y está vigente, se puede consultar con su folio fiscal en el servicio de verificación de CFDI del SAT. Revisa la dirección vigente en sat.gob.mx."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un RFC de 12 caracteres corresponde a…","ops":["Una persona moral (empresa)","Una persona física","Un extranjero sin RFC"],"correcta":0,"explica":"Las personas físicas tienen 13 caracteres porque su RFC incluye una letra más del nombre."},{"p":"Si la factura trae el código postal de una sucursal y no el del domicilio fiscal…","ops":["Se corrige a mano sobre el PDF","Se acepta porque es un detalle","Se pide al proveedor que la cancele y la emita de nuevo"],"correcta":2},{"p":"El uso S01 significa…","ops":["Adquisición de mercancías","Sin efectos fiscales","Gastos en general"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la factura con el código postal de la sucursal</b><br>Una auxiliar en una cadena de gimnasios en León recibió la factura de un proveedor de equipo. El RFC estaba bien, pero el nombre venía con «S.A. de C.V.», el código postal era el de la sucursal y el uso del CFDI no correspondía. Ella la mandó a pagar. El contador la rechazó un mes después.<br>En CFDI 4.0, los datos del receptor deben coincidir con la constancia de situación fiscal. Si algo no coincide, se pide cancelación y nueva factura por escrito."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Contra qué se revisan los datos del receptor?","ops":["Contra la constancia de situación fiscal de la empresa","Contra la tarjeta de presentación","Contra la factura anterior"],"correcta":0,"explica":"La constancia es la fuente oficial."},{"p":"¿Qué código postal debe llevar?","ops":["El de la sucursal que compró","El del domicilio fiscal","Cualquiera de la empresa"],"correcta":1,"explica":"Debe coincidir con el registrado ante el SAT."},{"p":"Si la factura trae un error, ¿qué haces?","ops":["Corregirla con pluma","Pedir por escrito la cancelación y una nueva factura","Pagarla igual"],"correcta":1,"explica":"Una factura con error se sustituye."}]},{"tipo":"comparar","titulo":"Cómo se pide la corrección","mal":"«Oiga, la factura salió mal, a ver si la cambia.»","bien":"«Buen día. La factura folio 1234 trae el código postal de la sucursal; el fiscal es 37000 y el uso correcto es G03. ¿Nos apoya con la cancelación y una nueva? Adjunto nuestra constancia.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe la lista de revisión que aplicarías a cada factura recibida antes de mandarla a pago.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Redacta el correo para pedir la corrección de una factura con dos errores.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Revisión de CFDI recibido","texto":"REVISIÓN DE FACTURA RECIBIDA\nFolio: [ ]   Proveedor: [ ]\n□ RFC del receptor igual al de la constancia\n□ Nombre exacto, sin régimen de capital\n□ Código postal del domicilio fiscal\n□ Régimen fiscal correcto\n□ Uso del CFDI indicado por la empresa\n□ Coincide con la orden de compra y lo recibido\n□ PUE o PPD según cómo se pagará\nResultado: □ Aprobada para pago  □ Solicitar corrección (fecha: )\nDudas fiscales → contador","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["En CFDI 4.0 los datos del receptor deben coincidir con la constancia de situación fiscal.","Revisa RFC, nombre sin régimen de capital, código postal fiscal, régimen y uso del CFDI.","Si algo no coincide, pide cancelación y nueva factura por escrito; las dudas fiscales van con el contador."]}],"d-asistente-administrativo-m4-lab":[{"tipo":"destacado","texto":"Es el último día del mes en <b>Distribuidora Norte</b>, en Saltillo. Tu jefa te pide: arquear la caja chica ($4,000 de fondo), revisar la comprobación de viáticos de un vendedor, actualizar el inventario de papelería y revisar tres facturas de proveedores antes de pagarlas."},{"tipo":"texto","texto":"<p><b>Escena 1 — La caja chica.</b> Cuentas $980 en efectivo y $2,870 en comprobantes; hay un vale de $150 sin firma.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 1","pregunta":"Escribe el resultado del arqueo y cómo lo reportas.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 2 — Los viáticos.</b> Anticipo $5,000; comprobó $4,600, de los cuales $500 no tienen factura.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 2","pregunta":"Escribe quién le debe a quién y qué observaciones haces.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 3 — El inventario.</b> Quedan 3 paquetes de hojas (mínimo 5) y 1 tóner (mínimo 2).</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 3","pregunta":"Escribe la requisición y el flujo de compra.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"texto","texto":"<p><b>Escena 4 — Las facturas.</b> Una trae el código postal de la sucursal y otra cobra 10 cajas cuando llegaron 8.</p>"},{"tipo":"reflexion","rotulo":"Tu respuesta — escena 4","pregunta":"Escribe qué haces con cada una.","ayuda":"Escribe como si estuvieras ahí. No hay una sola respuesta correcta."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"Resultado del arqueo:","ops":["Cuadra","Sobrante de $150","Faltante de $150"],"correcta":2,"explica":"980 + 2,870 = 3,850; faltan 150."},{"p":"En los viáticos, el vendedor…","ops":["recibe $400","no debe nada","devuelve $400"],"correcta":2,"explica":"5,000 − 4,600 = 400 a devolver."},{"p":"La factura de 10 cajas cuando llegaron 8…","ops":["no se paga hasta que se corrija o se reciba lo faltante","se paga la mitad","se paga completa"],"correcta":0,"explica":"Se compara orden, recepción y factura."}]},{"tipo":"plantilla","rotulo":"Cierre de mes administrativo","texto":"CIERRE DE MES — [Mes]\n□ Arqueo de caja chica y reposición\n□ Comprobaciones de viáticos\n□ Inventario de papelería y requisición\n□ Facturas recibidas revisadas contra orden y recepción\n□ Facturas con error: solicitud de corrección enviada\n□ Reporte a la jefa con diferencias y pendientes","nota":"Cópiala y úsala en tu trabajo."}],"d-asistente-administrativo-m5-l1":[{"tipo":"texto","texto":"Casi todas las oficinas trabajan con uno de dos paquetes: <b>Google Workspace</b> o <b>Microsoft 365</b>. Hacen lo mismo con distinto nombre. Si aprendes la idea de cada herramienta, te adaptas rápido a la que use tu nueva oficina. Los menús cambian seguido, así que aquí aprendes <b>qué hace cada una</b>, no dónde está cada botón al momento de escribir."},{"tipo":"tabla","titulo":"Lo mismo con distinto nombre","encabezados":["Para qué","Google Workspace","Microsoft 365"],"filas":[["Correo","Gmail","Outlook"],["Calendario","Google Calendar","Calendario de Outlook"],["Documentos de texto","Documentos de Google","Word"],["Hojas de cálculo","Hojas de cálculo de Google","Excel"],["Guardar y compartir archivos","Google Drive","OneDrive y SharePoint"],["Videollamadas y chat","Google Meet y Chat","Microsoft Teams"],["Encuestas y registros","Formularios de Google","Microsoft Forms"]]},{"tipo":"pasos","rotulo":"Compartir un archivo sin riesgos","pasos":["Guárdalo en la carpeta compartida correcta, con la regla de nombres de la oficina.","Comparte con personas concretas (por correo), no con «cualquiera que tenga el enlace», salvo que sea algo público.","Elige el permiso justo: <b>lector</b> (solo ve), <b>comentarista</b> (sugiere) o <b>editor</b> (cambia).","Manda el enlace, no un archivo adjunto nuevo: así todos trabajan sobre la misma versión.","Cuando el proyecto termine o alguien salga de la empresa, quita los accesos que ya no hacen falta."]},{"tipo":"lista","items":["<b>Calendario compartido:</b> cada cita con título claro («Cita: Ing. Robles — contrato»), lugar o liga, y descripción con lo que hay que llevar. Usa colores por tipo (externas, internas, personales bloqueadas).","<b>Ver disponibilidad:</b> antes de proponer una junta, revisa los calendarios compartidos para no empalmar.","<b>Formularios:</b> sirven para registrar asistencia a un curso, pedir datos para una cita o hacer una encuesta de satisfacción. Las respuestas caen solas en una hoja de cálculo."]},{"tipo":"relacionar","rotulo":"¿Qué herramienta usas?","pares":[["Registrar quién asistirá a la capacitación","Formulario"],["Ver si el jefe está libre el jueves a las 11","Calendario compartido"],["Que tres personas editen la misma cotización","Documento en la nube"],["Reunión con un cliente que está en otra ciudad","Videollamada"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Excel en Microsoft 365 equivale en Google a…","ops":["Hojas de cálculo de Google","Documentos de Google","Google Drive"],"correcta":0,"explica":"Ambos manejan fórmulas como SUMA, CONTAR.SI o BUSCARV."},{"p":"Para que alguien vea una cotización sin poder cambiarla, le das permiso de…","ops":["Editor","Propietario","Lector"],"correcta":2},{"p":"Compartir con «cualquiera que tenga el enlace» un archivo con datos de clientes es…","ops":["Obligatorio para trabajar en equipo","Un riesgo, porque el enlace puede reenviarse a cualquiera","La forma más segura"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: el archivo compartido «con cualquiera que tenga el enlace»</b><br>En una inmobiliaria de Mérida, la asistente compartió la carpeta de contratos con un cliente usando «cualquiera con el enlace puede editar». El cliente reenvió el enlace a su abogado, este a un conocido, y alguien borró un contrato. Además, dos asesores agendaron visitas a la misma casa a la misma hora porque cada uno usaba su propio calendario.<br>Comparte con personas concretas y el permiso justo. Calendario compartido para no empalmar y formularios para registrar datos sin capturarlos a mano."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué permiso debió dar?","ops":["Solo al correo del cliente y solo lectura, a un documento, no a toda la carpeta","Editar a cualquiera con el enlace","Ninguno"],"correcta":0,"explica":"El permiso justo protege los documentos."},{"p":"¿Qué evita el empalme de visitas?","ops":["Llamarse antes de cada visita","Que cada quien use su libreta","Un calendario compartido del equipo"],"correcta":2,"explica":"Todos ven la disponibilidad real."},{"p":"Google Workspace y Microsoft 365…","ops":["hacen lo mismo con distinto nombre","no tienen nada en común","son solo para empresas grandes"],"correcta":0,"explica":"Aprende la idea, no el botón."}]},{"tipo":"comparar","titulo":"Cómo se comparte un documento","mal":"«Te mando el enlace de la carpeta, ahí está todo.»","bien":"«Te compartí solo el contrato de tu casa, en modo lectura, a tu correo. Si necesitas otro documento, me dices.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Revisa los archivos que compartes (o que comparte una oficina que conozcas) y escribe cuáles tienen permisos de más y cómo los corregirías.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Diseña un formulario para una necesidad real de oficina (solicitud de vacaciones, registro de visitas, pedido de papelería) con sus preguntas.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Equivalencias y reglas para compartir","texto":"EQUIVALENCIAS\nGoogle Docs ↔ Word · Hojas de cálculo ↔ Excel · Drive ↔ OneDrive · Calendar ↔ Outlook · Forms ↔ Forms · Meet ↔ Teams\n\nREGLAS PARA COMPARTIR\n1. A personas concretas, no «a cualquiera con el enlace».\n2. Permiso mínimo: ver < comentar < editar.\n3. Documento, no carpeta completa, si solo necesita uno.\n4. Revisión mensual de accesos: quitar los que ya no se usan.","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Google Workspace y Microsoft 365 hacen lo mismo con distinto nombre: aprende la idea, no el botón.","Comparte con personas concretas y el permiso justo; quita accesos que ya no se usan.","Calendario compartido para no empalmar y formularios para registrar datos sin capturarlos a mano."]}],"d-asistente-administrativo-m5-l2":[{"tipo":"texto","texto":"En recepción y en asistencia todo parece urgente: el teléfono, el jefe que pide algo «rapidito», el proveedor en la puerta. Si todo es urgente, nada se termina. La solución es tener <b>una sola lista</b> de pendientes (no diez papelitos) y decidir el orden con un criterio, no con el que grita más fuerte."},{"tipo":"tabla","titulo":"Matriz de urgente e importante","encabezados":["","Urgente","No urgente"],"filas":[["<b>Importante</b>","<b>Hazlo ya:</b> el paciente en la puerta, el contrato que vence hoy","<b>Agéndalo:</b> organizar el archivo, preparar el viaje del próximo mes"],["<b>No importante</b>","<b>Resuélvelo rápido o delega:</b> la mayoría de las interrupciones","<b>Elimínalo o déjalo al final:</b> reenviar cadenas, revisar redes"]],"nota":"A esta forma de ordenar se le conoce como matriz de Eisenhower. Lo importante agendado a tiempo evita que se vuelva urgente."},{"tipo":"pasos","rotulo":"Tu rutina de 10 minutos","pasos":["Al llegar, revisa agenda del día, correos y recados pendientes.","Pasa todo a tu lista única (libreta, app o la lista de tareas de tu correo).","Marca las 3 cosas que sí o sí deben quedar hoy.","Bloquea tiempo en tu calendario para las tareas largas.","Antes de irte, tacha lo hecho y pasa lo pendiente a mañana con fecha."]},{"tipo":"comparar","titulo":"Cuando el jefe te pide algo nuevo","malTitulo":"Así no","mal":"Decir «sí» a todo y al final del día no terminar nada, o dejar a medias lo que ya habías prometido.","bienTitulo":"Así sí","bien":"«Claro. Ahorita estoy con la comprobación de viáticos que vence hoy a las 5. ¿Lo tuyo va primero o lo hago al terminar?». Dejas que el jefe decida con información."},{"tipo":"practica","rotulo":"¿En qué cuadro va?","preguntas":[{"p":"El contrato que hay que entregar firmado hoy antes de las 2","ops":["Importante y urgente","Importante y no urgente","No importante y no urgente"],"correcta":0,"explica":"Tiene consecuencia y fecha hoy."},{"p":"Depurar el archivo muerto del año pasado","ops":["Importante y urgente","No importante y urgente","Importante y no urgente"],"correcta":2},{"p":"Reenviar una cadena de chistes al grupo de la oficina","ops":["Importante y no urgente","No importante y no urgente","Importante y urgente"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu lista de hoy","pregunta":"Escribe 6 pendientes que tengas hoy (del trabajo, estudio o casa) y acomódalos en los cuatro cuadros. ¿Cuáles son tus 3 «sí o sí»?","ayuda":"Hazlo ya:… / Agéndalo:… / Rápido o delega:… / Elimina:…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: todo es urgente</b><br>Mariana, asistente de dirección en una empresa de alimentos en Irapuato, empieza el día con 25 pendientes en papelitos pegados a la pantalla. Cada vez que alguien le pide algo, lo empieza. Al final del día, lo que el director necesitaba para la junta con el banco quedó a medias.<br>Una sola lista de pendientes. Urgente e importante: hazlo ya; importante no urgente: agéndalo antes de que arda. Si te piden algo nuevo, di en qué estás y deja que tu jefe elija la prioridad."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Dónde va la presentación para el banco de mañana?","ops":["Ni urgente ni importante","Urgente e importante: hacerla primero","Importante no urgente"],"correcta":1,"explica":"Tiene fecha cercana y alto impacto."},{"p":"Actualizar el directorio de proveedores (sin fecha) es…","ops":["urgente e importante","importante no urgente: agendarlo","eliminable"],"correcta":1,"explica":"Si no se agenda, algún día arderá."},{"p":"Si un gerente le pide algo nuevo, Mariana debe…","ops":["decir que no","dejar todo y hacerlo","decir en qué está y pedir que su jefe defina la prioridad"],"correcta":2,"explica":"Así la prioridad la decide quien tiene la visión completa."}]},{"tipo":"comparar","titulo":"Cómo se responde a un pedido nuevo","mal":"«Sí, ahorita lo hago.» (y deja la presentación)","bien":"«Con gusto. Estoy terminando la presentación del banco para las 5. ¿Lo necesitas antes o puede ser mañana a primera hora?»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe todos tus pendientes de esta semana (del trabajo, la escuela o la casa) en una sola lista y clasifícalos en la matriz urgente/importante.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe tres frases que usarías para negociar prioridades con un jefe sin sonar grosera.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Matriz de prioridades del día","texto":"PENDIENTES — [Fecha]\nPendiente | ¿Urgente? | ¿Importante? | Cuadrante | Hora\n[ ] | [sí/no] | [sí/no] | [=SI(Y(B2=\"sí\",C2=\"sí\"),\"1 Hacer ya\",SI(C2=\"sí\",\"2 Agendar\",SI(B2=\"sí\",\"3 Delegar o resolver rápido\",\"4 Eliminar\")))] | [ ]\n\nTres cosas que sí o sí termino hoy: 1. [ ] 2. [ ] 3. [ ]","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["Una sola lista de pendientes, no papelitos sueltos.","Urgente e importante: hazlo ya; importante no urgente: agéndalo antes de que arda.","Si te piden algo nuevo, di en qué estás y deja que tu jefe elija la prioridad."]}],"d-asistente-administrativo-m5-l3":[{"tipo":"texto","texto":"Las herramientas de inteligencia artificial (como ChatGPT, Gemini, Copilot o Claude) ayudan mucho en una oficina: un borrador de correo, un oficio más formal, un resumen de notas para la minuta. Pero son un <b>ayudante</b>, no alguien que firma por ti: <b>tú revisas y respondes</b> por lo que se envía. Y lo más importante: <b>no pegues en ellas datos personales ni información confidencial</b>, salvo que tu empresa tenga una herramienta aprobada y una política que lo permita."},{"tipo":"comparar","titulo":"Cómo pedirle un borrador a la IA","malTitulo":"Riesgoso","mal":"«Redacta un correo para Martha Gómez Ruiz, paciente con diabetes, tel. 33 1234 5678, para decirle que su estudio salió alterado».","bienTitulo":"Seguro","bien":"«Redacta un correo breve y amable para una paciente, pidiéndole que llame al consultorio para agendar una cita de revisión de resultados. Sin mencionar diagnóstico. Tono formal, en español de México»."},{"tipo":"plantilla","rotulo":"Instrucción para un borrador con IA","texto":"Actúa como asistente administrativa de un [tipo de lugar] en México.\nRedacta un [correo / oficio / mensaje de WhatsApp] para [tipo de destinatario, sin nombre real].\nObjetivo: [qué quieres lograr].\nDatos que debe incluir: [fecha, hora, lugar — usa datos genéricos].\nTono: [formal / cordial] y en español de México, tuteando o de usted según [indicación].\nExtensión: máximo [número] líneas.\nNo inventes datos que no te di.","nota":"Después, en tu correo o documento, cambias los datos genéricos por los reales y revisas todo antes de enviar."},{"tipo":"destacado","texto":"<b>Datos personales en México.</b> Las empresas que manejan datos personales deben tener un <b>aviso de privacidad</b> y usar los datos solo para lo que ahí dicen. La ley vigente para particulares es la nueva <b>Ley Federal de Protección de Datos Personales en Posesión de los Particulares</b>, publicada en marzo de 2025; con ella, las funciones que tenía el INAI pasaron a la <b>Secretaría Anticorrupción y Buen Gobierno</b>. Verifica en gob.mx el detalle vigente y la política de tu empresa."},{"tipo":"tabla","titulo":"Lo que debes saber en tu puesto","encabezados":["Concepto","Qué significa para ti"],"filas":[["<b>Dato personal</b>","Cualquier información de una persona identificada o identificable: nombre, teléfono, correo, domicilio, CURP"],["<b>Dato sensible</b>","Salud, origen étnico, creencias religiosas, preferencia sexual, opiniones políticas, entre otros. Se cuidan todavía más"],["<b>Aviso de privacidad</b>","Documento donde la empresa dice qué datos pide, para qué y cómo ejercer derechos; debe estar a la vista o disponible"],["<b>Derechos ARCO</b>","Acceso, Rectificación, Cancelación y Oposición: la persona puede pedir ver, corregir, borrar u oponerse al uso de sus datos. Si alguien lo pide, canaliza con el responsable"]]},{"tipo":"relacionar","rotulo":"¿Qué derecho ARCO pide?","pares":[["«Quiero saber qué datos míos tienen»","Acceso"],["«Mi teléfono cambió, corríjanlo»","Rectificación"],["«Bórrenme de su base de datos»","Cancelación"],["«No quiero que usen mis datos para publicidad»","Oposición"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué sí puedes pegar en una IA pública para pedir un borrador?","ops":["Una situación genérica sin nombres ni datos reales","El expediente de un paciente","La lista de sueldos de la empresa"],"correcta":0,"explica":"Describe la situación con datos genéricos y completa lo real después."},{"p":"La IA te da un oficio con una fecha que tú no le diste. Tú…","ops":["La dejas, porque la IA sabe más","Envías el oficio sin leerlo","La corriges y revisas todo antes de enviarlo"],"correcta":2},{"p":"Un cliente pide que borren sus datos de la base de la empresa. Está ejerciendo su derecho de…","ops":["Acceso","Cancelación","Rectificación"],"correcta":1}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la lista de pacientes en la herramienta de IA</b><br>Una recepcionista de un laboratorio clínico en Puebla quería mandar recordatorios más amables. Copió la lista de pacientes con nombres, teléfonos y estudios pendientes en una herramienta de IA gratuita y le pidió «escribe un mensaje para cada uno». Días después, un paciente pidió saber qué datos suyos tenía el laboratorio y nadie supo a quién canalizarlo.<br>La IA hace borradores; tú revisas. No pegues datos personales en herramientas no aprobadas. Si alguien ejerce sus derechos ARCO, se canaliza con el responsable."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cómo pudo usar la IA sin exponer datos?","ops":["No hay forma","Pegando solo la mitad de la lista","Pidiendo una plantilla general con espacios para nombre y fecha, sin pegar la lista"],"correcta":2,"explica":"La IA sirve para el borrador; los datos se ponen después, fuera de ella."},{"p":"Los estudios de laboratorio de un paciente son…","ops":["datos sin importancia","datos sensibles de salud","datos públicos"],"correcta":1,"explica":"Requieren protección especial."},{"p":"¿Qué son los derechos ARCO?","ops":["Acceso, rectificación, cancelación y oposición sobre los datos personales","Un tipo de archivo","Una norma de seguridad industrial"],"correcta":0,"explica":"Se atienden conforme al aviso de privacidad, con el responsable designado."}]},{"tipo":"comparar","titulo":"Cómo se pide a la IA","mal":"«Aquí está mi lista de 80 pacientes con sus estudios, escríbeles a cada uno.»","bien":"«Escribe un recordatorio amable de 40 palabras para un paciente que tiene un estudio pendiente, con espacios [NOMBRE] y [FECHA]. Sin mencionar el tipo de estudio.»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Escribe tres tareas de oficina en las que usarías IA para hacer borradores y, para cada una, qué datos nunca pondrías y cómo revisarías el resultado.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"plantilla","rotulo":"Uso responsable de IA en la oficina","texto":"IA EN LA OFICINA\nSÍ: borradores de correos, avisos, minutas a partir de tus notas sin datos personales, ideas, corrección de estilo.\nNO: datos personales de clientes o pacientes, información confidencial, contraseñas, contratos completos en herramientas no aprobadas.\nREVISIÓN: datos correctos · tono · ortografía · que no invente nada.\nDerechos ARCO: canalizar a [responsable de datos personales].","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["La IA hace borradores; tú revisas y respondes por lo que se envía.","No pegues datos personales ni información confidencial en herramientas no aprobadas.","Aviso de privacidad y derechos ARCO: si alguien los pide, canaliza con el responsable."]}],"d-asistente-administrativo-m5-l4":[{"tipo":"texto","texto":"Eres Laura, recepcionista y asistente en el <b>Despacho Herrera y Asociados</b>, en Guadalajara. Son las 9:00 del lunes. Tu jefa, la Lic. Herrera, llega a las 10:00. En tu escritorio tienes: tres recados del viernes, dos citas que confirmar, un proveedor que viene a entregar papelería, la caja chica por arquear y una factura por revisar. Además, cada rato te piden extensiones y áreas del personal: para eso vas a armar un <b>directorio con BUSCARV</b>."},{"tipo":"excel","rotulo":"Directorio del Despacho Herrera","datos":[["Nombre","Área","Extensión","Correo","","Buscar","Extensión","Área"],["Castillo Mora Andrea","Dirección",101,"acastillo@herrera.mx","","Gómez Ruiz Tomás","",""],["Díaz Peña Roberto","Contabilidad",205,"rdiaz@herrera.mx","","Flores Vega Irma","",""],["Flores Vega Irma","Contabilidad",206,"iflores@herrera.mx","","Pérez Luna Omar","",""],["Gómez Ruiz Tomás","Jurídico",310,"tgomez@herrera.mx"],["Ramírez Ortiz Julia","Jurídico",311,"jramirez@herrera.mx"],["Sánchez Lara Pablo","Sistemas",402,"psanchez@herrera.mx"],["","","","","","Personas en Contabilidad",""]],"retos":[{"celda":"G2","formula":"=BUSCARV(F2,$A$2:$D$7,3,FALSO)","esperado":310,"requiere":"BUSCARV(","texto":"<b>G2</b>: busca la extensión de la persona de F2. BUSCARV busca en la primera columna del rango y devuelve la columna que le indiques (la extensión es la 3). Usa FALSO para coincidencia exacta.","pista":"=BUSCARV(F2,$A$2:$D$7,3,FALSO)"},{"celda":"H2","formula":"=BUSCARV(F2,$A$2:$D$7,2,FALSO)","esperado":"Jurídico","requiere":"BUSCARV(","texto":"<b>H2</b>: ahora trae su área (columna 2 del rango)."},{"celda":"G3","formula":"=BUSCARV(F3,$A$2:$D$7,3,FALSO)","esperado":206,"requiere":"BUSCARV(","texto":"<b>G3</b>: extensión de Irma Flores."},{"celda":"G4","formula":"=SI.ERROR(BUSCARV(F4,$A$2:$D$7,3,FALSO),\"No está en el directorio\")","esperado":"No está en el directorio","requiere":"SI.ERROR(","texto":"<b>G4</b>: Omar Pérez no trabaja aquí. Envuelve BUSCARV en SI.ERROR para que, en lugar de #N/D, diga «No está en el directorio».","explica":"Alguien que pregunta por una persona que no trabaja ahí puede ser un error… o alguien sacando información. Responde con cortesía, sin dar datos de otros."},{"celda":"G8","formula":"=CONTAR.SI(B2:B7,\"Contabilidad\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>G8</b>: cuenta cuántas personas hay en Contabilidad."}]},{"tipo":"practica","rotulo":"Resuelve la mañana de Laura","preguntas":[{"p":"9:00. ¿Qué haces primero?","ops":["Revisar agenda, recados y pendientes y armar tu lista del día","Arquear la caja chica","Contestar mensajes personales"],"correcta":0,"explica":"Diez minutos de orden al llegar te ahorran una mañana de carreras."},{"p":"9:20. Uno de los recados dice solo «Te buscó el de la notaría». Tú…","ops":["Se lo das así a la jefa","Lo tiras porque está incompleto","Revisas el registro de llamadas o marcas a la notaría para completar el recado antes de que llegue la jefa"],"correcta":2},{"p":"9:40. Llega el proveedor con la papelería. Tú…","ops":["Le pagas de la caja chica aunque pasa del monto máximo","Revisas contra la orden de compra, firmas de recibido y pides la factura","Firmas sin revisar para no hacerlo esperar"],"correcta":1},{"p":"10:15. La factura del proveedor dice «Papelera del Bajío SA de CV» como receptor en lugar del nombre del despacho. Tú…","ops":["Pides por escrito que la cancele y emita una nueva con los datos correctos","La aceptas porque el importe está bien","La corriges a mano"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena el cierre del día","items":[{"frase":"Arqueo caja chica recados entregados lista para mañana"},{"frase":"Confirmé las citas de mañana por WhatsApp"}]},{"tipo":"reflexion","rotulo":"Tu plan de 90 días","pregunta":"Imagina que ya conseguiste el empleo. ¿Qué tres cosas de este diplomado aplicarías en tus primeros 90 días para que tu jefe note la diferencia? Por ejemplo: formato de recados, regla de nombres, control de citas en hoja de cálculo.","ayuda":"En mi primer mes… En el segundo… Al tercer mes quiero que…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso: la extensión que nunca existió</b><br>La recepcionista de una universidad en Toluca busca extensiones en una lista impresa de hace dos años. Transfiere llamadas a personas que ya no trabajan ahí. Su coordinadora armó un directorio en hoja de cálculo con BUSCARV, pero cuando escribe un nombre que no está, sale #N/D y la recepcionista cree que «se descompuso».<br>BUSCARV con FALSO trae la extensión exacta; SI.ERROR evita el #N/D. Un buen día en recepción empieza con lista, recados completos y agenda confirmada."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué argumento de BUSCARV busca coincidencia exacta?","ops":["VERDADERO","0.5","FALSO"],"correcta":2,"explica":"Con FALSO, busca exactamente el valor."},{"p":"¿Qué muestra =SI.ERROR(BUSCARV(A2,Directorio!A:C,3,FALSO),\"No encontrado\")?","ops":["Un error","Siempre «No encontrado»","La extensión o, si no existe, «No encontrado»"],"correcta":2,"explica":"SI.ERROR reemplaza el #N/D por un mensaje claro."},{"p":"¿Cada cuánto actualizar el directorio?","ops":["Cada vez que hay altas o bajas de personal, con revisión mensual","Nunca","Cada dos años"],"correcta":0,"explica":"Un directorio viejo genera transferencias perdidas."}]},{"tipo":"comparar","titulo":"Cómo se ve la búsqueda","mal":"«#N/D»","bien":"«Nombre: Laura Pérez → Área: Servicios Escolares → Ext. 2140» o «No encontrado: pregunta a Recursos Humanos»"},{"tipo":"reflexion","rotulo":"Escribe tu respuesta al caso","pregunta":"Arma un directorio de diez personas con nombre, área, extensión y correo, y escribe las fórmulas para buscar por nombre sin que aparezca #N/D.","ayuda":"Escribe con tus palabras. Revisa que cubras cada parte de la consigna."},{"tipo":"reflexion","rotulo":"Da un paso más","pregunta":"Escribe tu rutina de los primeros 20 minutos del día en una recepción.","ayuda":"Aplícalo a tu propio trabajo o a una situación que conozcas."},{"tipo":"plantilla","rotulo":"Directorio con BUSCARV","texto":"DIRECTORIO (hoja «Directorio»)\nNombre | Área | Extensión | Correo\n\nBUSCADOR\nEscribe el nombre: [A2]\nÁrea: [=SI.ERROR(BUSCARV(A2,Directorio!A:D,2,FALSO),\"No encontrado\")]\nExtensión: [=SI.ERROR(BUSCARV(A2,Directorio!A:D,3,FALSO),\"No encontrado\")]\nCorreo: [=SI.ERROR(BUSCARV(A2,Directorio!A:D,4,FALSO),\"No encontrado\")]\n\nRUTINA DE APERTURA: lista del día · agenda confirmada · recados pendientes · correo · área limpia","nota":"Cópiala y adáptala a tu trabajo."},{"tipo":"clave","items":["BUSCARV con FALSO trae extensión o área exacta; SI.ERROR evita el #N/D.","Un buen día en recepción empieza con lista, recados completos y agenda confirmada.","Revisa lo que recibes y lo que pagas contra la orden de compra y la constancia fiscal."]}],"d-asistente-administrativo-m5-lab":[{"tipo":"destacado","texto":"Este es tu proyecto final. Vas a armar el <b>manual de puesto de asistente administrativa o recepcionista</b> para un lugar real o que conozcas bien (consultorio, escuela, despacho, empresa, hotel), y un <b>portafolio</b> con tus documentos modelo. Al terminar tendrás algo concreto que mostrar a un empleador."},{"tipo":"texto","texto":"<p><b>Parte 1 — El puesto y tu postulación.</b> Con lo del módulo 1.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 1","pregunta":"Escribe las funciones del puesto, tus reglas de confidencialidad y tu CV de una página adaptado a ese lugar.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"texto","texto":"<p><b>Parte 2 — Atención y comunicación.</b> Con lo del módulo 2.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 2","pregunta":"Escribe el protocolo de atención presencial y telefónica, el formato de recado, un correo modelo y el procedimiento de quejas.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"texto","texto":"<p><b>Parte 3 — Documentos y organización.</b> Con lo del módulo 3.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 3","pregunta":"Escribe la estructura de archivo, la regla de nombres, una minuta modelo y un oficio modelo.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"texto","texto":"<p><b>Parte 4 — Administración y herramientas.</b> Con lo de los módulos 4 y 5.</p>"},{"tipo":"reflexion","rotulo":"Tu entrega — parte 4","pregunta":"Escribe las reglas de caja chica, el inventario con punto de reorden, la revisión de facturas, las reglas para compartir archivos y el uso responsable de IA.","ayuda":"Hazlo sobre un caso real o que conozcas bien. Guarda tu texto: al final tendrás tu proyecto completo."},{"tipo":"practica","rotulo":"Revisa tus decisiones","preguntas":[{"p":"¿Qué hace valioso tu portafolio en una entrevista?","ops":["Que sea largo","Que muestra documentos concretos que sabes hacer","Que tenga muchos colores"],"correcta":1,"explica":"Demuestra en lugar de solo decir."},{"p":"Un recado completo incluye…","ops":["solo el teléfono","para quién, de quién, teléfono confirmado, mensaje, acción, urgencia, hora y quién lo tomó","solo el nombre"],"correcta":1,"explica":"Así nadie tiene que volver a preguntar."},{"p":"En el arqueo, efectivo + comprobantes debe ser igual a…","ops":["las ventas del día","cero","el fondo fijo"],"correcta":2,"explica":"Si no, hay faltante o sobrante."},{"p":"Una factura con datos que no coinciden con la constancia…","ops":["se archiva","se pide corregir antes de pagar","se paga"],"correcta":1,"explica":"Los datos deben coincidir con el SAT."},{"p":"Tu constancia de este diplomado es…","ops":["una constancia libre de Instituto Mara, no validez SEP ni certificación CONOCER","un título técnico","una certificación oficial"],"correcta":0,"explica":"Dilo así en tu CV."}]},{"tipo":"plantilla","rotulo":"Índice del manual y portafolio","texto":"MANUAL DE PUESTO Y PORTAFOLIO\n[Lugar] · [Tu nombre] · [Fecha]\n\n1. Funciones del puesto y reglas de confidencialidad\n2. CV y carta de presentación\n3. Protocolo de atención presencial y telefónica\n4. Formatos: recado, registro de visitantes, control de citas\n5. Correo, minuta, oficio y memorándum modelo\n6. Estructura de archivo y regla de nombres\n7. Caja chica, viáticos, inventario y compras\n8. Revisión de facturas\n9. Herramientas, permisos e IA responsable\n10. Directorio con BUSCARV","nota":"Úsala como índice de tu proyecto final."}]},"q":{"d-asistente-administrativo-m1":[{"p":"Este diplomado es…","ops":["Un título técnico con validez oficial de la SEP y cédula","Una certificación de CONOCER","Una licenciatura en administración","Un diplomado libre con constancia de Instituto Mara"],"correcta":3},{"p":"En un consultorio, lo que más debe cuidar la recepcionista con la información es…","ops":["Dar informes completos a cualquier familiar que llame preguntando","La confidencialidad de los datos de salud de los pacientes","Publicar las citas en redes sociales"],"correcta":1},{"p":"Una llamada pide la hora de la cita de otra persona. La respuesta correcta es…","ops":["Colgar sin decir nada","No dar la información y ofrecer que esa persona se comunique","Dar la hora pero no el motivo","Dar la información si la persona suena amable y conoce los datos"],"correcta":1},{"p":"Un proveedor ofrece un regalo para que su pago salga antes. Eso es…","ops":["Una prestación laboral","Un descuento por pronto pago","Un conflicto de interés"],"correcta":2},{"p":"Para que los filtros automáticos encuentren tu CV conviene…","ops":["Poner tu CV en tres páginas con diseño llamativo","Agregar una foto grande","Escribir todo en mayúsculas","Usar las mismas palabras clave de la vacante"],"correcta":3},{"p":"¿Cuál describe mejor un logro en el CV?","ops":["«Confirmé citas un día antes y bajaron las inasistencias»","«Responsable de recepción»","«Persona trabajadora, honesta y con muchas ganas de aprender»"],"correcta":0},{"p":"Te piden depositar dinero para «apartar tu lugar» en una vacante. Es…","ops":["Una fianza reembolsable obligatoria","Señal de fraude","Práctica normal de Recursos Humanos","Un requisito de la ley"],"correcta":1},{"p":"A la pregunta «¿Cuánto quieres ganar?» lo más recomendable es…","ops":["Pedir el doble para negociar","Dar un rango investigado para el puesto en tu ciudad","Decir «lo que me quieran pagar, lo importante es aprender»"],"correcta":1}],"d-asistente-administrativo-m2":[{"p":"El saludo telefónico profesional incluye…","ops":["Solo «¿Bueno?»","El nombre del jefe, su horario de atención y la extensión directa","Saludo, nombre del lugar, tu nombre y oferta de ayuda"],"correcta":2},{"p":"Si dejas a alguien en espera, conviene regresar a la línea cada…","ops":["10 minutos","Nunca, hasta tener respuesta","30 a 40 segundos","3 minutos"],"correcta":2},{"p":"¿Qué dato de un recado conviene repetir en voz alta?","ops":["El teléfono","El color de voz de quien llama","La hora a la que colgaste"],"correcta":0},{"p":"=CONTAR.SI(D2:D20,\"Asistió\") sirve para…","ops":["Contar cuántas citas tienen el estado «Asistió»","Sumar el dinero de las citas","Buscar el nombre del paciente y su estado en la columna D","Ordenar la agenda"],"correcta":0},{"p":"Hubo 3 inasistencias de 12 citas. El porcentaje de inasistencia es…","ops":["3%","12.5%","36%","25%"],"correcta":3},{"p":"Un buen asunto de correo para una junta es…","ops":["«Junta de revisión de contrato — jueves 12, 11:00»","«Hola»","«Urgente!!! Favor de leer y responder hoy mismo»"],"correcta":0},{"p":"El WhatsApp de atención a clientes debe manejarse desde…","ops":["Cualquier número disponible","El número de la empresa","Tu número personal","El número de tu jefe"],"correcta":1},{"p":"Llega un técnico que nadie anunció. Lo correcto es…","ops":["Pedirle amablemente que se vaya, sin preguntar nada a nadie","Confirmar con el área correspondiente antes de dejarlo pasar","Dejarlo pasar si trae credencial"],"correcta":1}],"d-asistente-administrativo-m3":[{"p":"Para expedientes de pacientes, el método de archivo más práctico suele ser…","ops":["Cronológico por fecha de nacimiento","Por color de carpeta","Numérico por teléfono","Alfabético por apellido"],"correcta":3},{"p":"La documentación contable y fiscal, en general, se conserva…","ops":["Un año","Para siempre, sin ninguna excepción, y solo en papel","5 años, salvo excepciones que marca la ley","3 meses"],"correcta":2},{"p":"¿Cuál nombre de archivo sigue la regla del curso?","ops":["2026-05-08_Contrato_HotelLaPaz_v02","Contrato Hotel La Paz FINAL bueno.docx","Contrato 8 de mayo (2)"],"correcta":0},{"p":"Con A2=\"2026-05-08\", B2=\"Minuta\" y C2=\"v01\", la fórmula =A2&\"_\"&B2&\"_\"&C2 devuelve…","ops":["2026-05-08_Minuta_v01","2026-05-08 Minuta v01 (con espacios)","A2_B2_C2","#¿NOMBRE?"],"correcta":0},{"p":"Un acuerdo de minuta bien escrito incluye…","ops":["La opinión de cada asistente sobre el tema","Acción, responsable y fecha límite","Solo el tema"],"correcta":1},{"p":"Para comunicar algo formalmente a una dependencia de gobierno se usa…","ops":["Un recado","Una minuta","Un oficio","Un memorándum"],"correcta":2},{"p":"Un aviso interno de un área a otra de la misma empresa es un…","ops":["Oficio","Acta de asamblea","Memorándum"],"correcta":2},{"p":"Un día antes de una junta conviene…","ops":["Mandar la minuta","Confirmar asistencia, reservar sala y probar equipo","Cambiar el horario si surge algo más importante, sin avisar"],"correcta":1}],"d-asistente-administrativo-m4":[{"p":"En una caja chica de fondo fijo de $3,000, se gastaron $1,200 con comprobantes. En efectivo debe haber…","ops":["$4,200.00","$4,200","$1,200","$1,800"],"correcta":3},{"p":"El arqueo de caja chica consiste en…","ops":["Tirar los tickets viejos para no acumular papeles en la caja","Contar el efectivo y compararlo con lo que debe haber","Pedir más dinero"],"correcta":1},{"p":"Si en el arqueo falta dinero, lo correcto es…","ops":["Tomarlo del siguiente fondo para que cuadre la caja y avisar después","Revisar comprobantes y reportarlo por escrito si no aparece","Reponerlo en silencio","Ignorarlo hasta fin de mes"],"correcta":1},{"p":"Anticipo de viáticos de $5,000 y gastos comprobados de $5,300 autorizados. Procede…","ops":["Que el empleado devuelva $300","Nada","Reembolsar $300 al empleado"],"correcta":2},{"p":"El documento que se usa para pedir internamente una compra es…","ops":["La orden de compra","La factura","La minuta","La requisición"],"correcta":3},{"p":"Existencia inicial 8, entradas 12, salidas 15. La existencia final es…","ops":["20","11","5","35"],"correcta":2},{"p":"En CFDI 4.0, el nombre de una empresa receptora se escribe…","ops":["Como lo conozca el proveedor, con su nombre comercial","Como en su constancia, sin «S.A. de C.V.»","Con «S.A. de C.V.» al final","Abreviado"],"correcta":1},{"p":"Si una factura trae un dato del receptor equivocado, se le pide al proveedor…","ops":["Mandarle una nota por WhatsApp con el dato correcto","Cancelarla y emitir una nueva","Corregir el PDF a mano"],"correcta":1}],"d-asistente-administrativo-m5":[{"p":"El equivalente de Word en Google Workspace es…","ops":["Google Drive","Hojas de cálculo de Google","Google Meet","Documentos de Google"],"correcta":3},{"p":"Para que alguien pueda sugerir cambios sin editar directamente, le das permiso de…","ops":["Propietario del archivo","Comentarista","Editor"],"correcta":1},{"p":"Organizar el archivo del año pasado es una tarea…","ops":["Importante y no urgente: se agenda","Urgente y no importante: se delega","Ni importante ni urgente: se elimina"],"correcta":0},{"p":"Al usar una IA pública para redactar un correo a un paciente, lo correcto es…","ops":["Describir la situación sin nombres ni datos de salud","Pegar el expediente para que el correo quede más completo","Enviar el texto sin revisarlo","Incluir el teléfono del paciente"],"correcta":0},{"p":"La ley que regula los datos personales en empresas privadas en México es…","ops":["El Código Fiscal de la Federación y su reglamento para empresas privadas","La Ley Federal de Protección de Datos Personales en Posesión de los Particulares","La Ley Federal del Trabajo"],"correcta":1},{"p":"Los derechos ARCO son…","ops":["Aviso, Revisión, Copia y Oficio","Alta, Retiro, Cambio y Orden","Acceso, Rectificación, Cancelación y Oposición","Archivo, Registro, Control y Orden de documentos"],"correcta":2},{"p":"=BUSCARV(\"Gómez Ruiz Tomás\",A2:D7,3,FALSO) devuelve…","ops":["La tercera persona de la lista","Cuántas veces aparece ese nombre dentro del rango A2:D7","El dato de la tercera columna del rango para esa persona"],"correcta":2},{"p":"Para que BUSCARV muestre un mensaje en lugar de #N/D se usa…","ops":["SI.ERROR","CONTAR.SI","CONCATENAR","LARGO"],"correcta":0}]}});
